CREATE OR REPLACE FUNCTION "public"."accept_ride_offer"("p_offer_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_offer RECORD;
    v_ride_id UUID;
    v_driver_user_id UUID;
    v_balance INTEGER;
BEGIN
    -- Get the offer details
    SELECT * INTO v_offer FROM ride_offers WHERE id = p_offer_id;
    IF v_offer IS NULL OR v_offer.status != 'pending' THEN RETURN FALSE; END IF;
    
    v_ride_id := v_offer.ride_id;

    -- 1. DEBT LOCK CHECK
    -- Get the driver's auth user id
    SELECT user_id INTO v_driver_user_id FROM drivers WHERE id = v_offer.driver_id;
    
    -- Check balance
    v_balance := get_wallet_balance(v_driver_user_id);
    
    IF v_balance < 0 THEN
        -- Driver is in debt. Mark offer as expired and return false.
        UPDATE ride_offers SET status = 'expired' WHERE id = p_offer_id;
        
        -- Log debt lock event
        INSERT INTO ride_events (ride_id, event_type, actor_type, actor_id, metadata)
        VALUES (v_ride_id, 'driver_debt_lock', 'driver', v_offer.driver_id, jsonb_build_object('balance', v_balance));
        
        RETURN FALSE;
    END IF;

    -- 2. RIDE LOCKING
    PERFORM 1 FROM rides 
    WHERE id = v_ride_id 
    AND status = 'searching' 
    FOR UPDATE;

    IF NOT FOUND THEN 
        UPDATE ride_offers SET status = 'expired' WHERE id = p_offer_id;
        RETURN FALSE; 
    END IF;
    
    -- 3. ATOMIC UPDATE
    UPDATE ride_offers SET status = 'accepted' WHERE id = p_offer_id;
    UPDATE ride_offers SET status = 'expired' WHERE ride_id = v_ride_id AND id != p_offer_id;
    
    UPDATE rides 
    SET driver_id = v_offer.driver_id, 
        status = 'assigned', 
        updated_at = now() 
    WHERE id = v_ride_id;
    
    UPDATE drivers SET status = 'busy' WHERE id = v_offer.driver_id;
    
    INSERT INTO ride_events (ride_id, event_type, actor_type, actor_id, metadata)
    VALUES (v_ride_id, 'ride_assigned', 'driver', v_offer.driver_id, jsonb_build_object('offer_id', p_offer_id));
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."accept_ride_offer"("p_offer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_mid_ride_stop"("p_ride_id" "uuid", "p_place_name" "text", "p_lat" double precision, "p_lng" double precision, "p_address" "text" DEFAULT ''::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_max_order INTEGER;
    v_rider_id UUID;
    v_convenience_fee INTEGER := 500; -- $5.00 Mid-Ride Fee
    v_new_stop_id UUID;
BEGIN
    -- 1. Security Check: Only the rider can add a stop to their active ride
    SELECT rider_id INTO v_rider_id FROM public.rides WHERE id = p_ride_id AND status = 'in_progress';
    IF v_rider_id IS NULL OR v_rider_id != auth.uid() THEN
        RAISE EXCEPTION 'Unauthorized: Ride must be in_progress and owned by requester';
    END IF;

    -- 2. Determine Order
    SELECT COALESCE(MAX(stop_order), 0) INTO v_max_order FROM public.ride_stops WHERE ride_id = p_ride_id;

    -- 3. Insert Stop
    INSERT INTO public.ride_stops (ride_id, stop_order, place_name, place_address, lat, lng, status)
    VALUES (p_ride_id, v_max_order + 1, p_place_name, p_address, p_lat, p_lng, 'pending')
    RETURNING id INTO v_new_stop_id;

    -- 4. Update Ride Fare & Metadata
    UPDATE public.rides 
    SET 
        total_fare_cents = total_fare_cents + v_convenience_fee,
        updated_at = now()
    WHERE id = p_ride_id;

    -- 5. Trigger Event for Driver App
    INSERT INTO public.ride_events (ride_id, event_type, actor_type, actor_id, metadata)
    VALUES (p_ride_id, 'stop_added', 'rider', auth.uid(), jsonb_build_object('place_name', p_place_name, 'stop_id', v_new_stop_id));

    RETURN jsonb_build_object('success', true, 'stop_id', v_new_stop_id, 'new_fare_cents', (SELECT total_fare_cents FROM public.rides WHERE id = p_ride_id));
END;
$_$;


ALTER FUNCTION "public"."add_mid_ride_stop"("p_ride_id" "uuid", "p_place_name" "text", "p_lat" double precision, "p_lng" double precision, "p_address" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_assign_band_keychain"("p_band_id" "uuid", "p_tag_uid" "text", "p_label" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  INSERT INTO public.band_keychains (band_id, tag_uid, label)
  VALUES (p_band_id, p_tag_uid, COALESCE(p_label, ''))
  ON CONFLICT (tag_uid) DO UPDATE SET band_id = p_band_id, label = COALESCE(p_label, band_keychains.label)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."admin_assign_band_keychain"("p_band_id" "uuid", "p_tag_uid" "text", "p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_create_driver"("p_id" "uuid", "p_name" "text", "p_status" "text", "p_is_online" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF auth.uid() IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Only admins can create drivers';
    END IF;

    INSERT INTO public.drivers (id, name, status, is_online)
    VALUES (p_id, p_name, p_status, p_is_online);
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."admin_create_driver"("p_id" "uuid", "p_name" "text", "p_status" "text", "p_is_online" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_create_merchant_key"("p_merchant_id" "uuid", "p_raw_key" "text", "p_label" "text", "p_scopes" "text"[] DEFAULT '{order:read}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_key_hash TEXT;
BEGIN
    -- Only admins can create merchant keys
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    IF p_raw_key IS NULL OR length(p_raw_key) < 8 THEN
        RAISE EXCEPTION 'Key must be at least 8 characters';
    END IF;

    -- SHA-256 hash the raw key before storing
    v_key_hash := encode(digest(p_raw_key, 'sha256'), 'hex');

    INSERT INTO public.merchant_api_keys (merchant_id, key_hash, label, scopes, is_active)
    VALUES (p_merchant_id, v_key_hash, p_label, p_scopes, true);

    -- Return raw key so admin can show it to merchant once
    RETURN jsonb_build_object(
        'success', true,
        'raw_key', p_raw_key,
        'merchant_id', p_merchant_id,
        'label', p_label
    );
END;
$$;


ALTER FUNCTION "public"."admin_create_merchant_key"("p_merchant_id" "uuid", "p_raw_key" "text", "p_label" "text", "p_scopes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_create_surge_zone"("p_lat" double precision, "p_lng" double precision, "p_radius_m" integer, "p_multiplier" numeric, "p_reason" "text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE v_id UUID;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;
    IF p_multiplier < 1.0 OR p_multiplier > 5.0 THEN
        RAISE EXCEPTION 'multiplier must be between 1.0 and 5.0';
    END IF;
    INSERT INTO public.pricing_zones (name, boundary_geojson, multiplier, is_active,
        center_lat, center_lng, radius_meters, reason, expires_at)
    VALUES (p_reason, '{"type":"Point"}'::jsonb, p_multiplier, true,
        p_lat, p_lng, p_radius_m, p_reason, p_expires_at)
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."admin_create_surge_zone"("p_lat" double precision, "p_lng" double precision, "p_radius_m" integer, "p_multiplier" numeric, "p_reason" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_deactivate_surge_zone"("p_zone_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;
    UPDATE public.pricing_zones SET is_active = false, updated_at = now() WHERE id = p_zone_id;
END;
$$;


ALTER FUNCTION "public"."admin_deactivate_surge_zone"("p_zone_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_escape_action"("p_package_id" "uuid", "p_action" "text", "p_booking_ref" "text" DEFAULT NULL::"text", "p_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_pkg RECORD;
    v_participants INT;
    v_refunded INT := 0;
    v_rider_record RECORD;
BEGIN
    -- Validate action
    IF p_action NOT IN ('confirm', 'delay', 'refund_all') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid action. Use confirm, delay, or refund_all.');
    END IF;

    SELECT * INTO v_pkg FROM escape_packages WHERE id = p_package_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Package not found');
    END IF;

    -- ── CONFIRM ──────────────────────────────────────────────────
    IF p_action = 'confirm' THEN
        -- Update all confirmed/payment_pending participants to passport_pending
        UPDATE escape_group_participants
        SET status = 'passport_pending', confirmed_at = COALESCE(confirmed_at, now())
        WHERE package_id = p_package_id
          AND status IN ('confirmed', 'payment_pending');

        GET DIAGNOSTICS v_participants = ROW_COUNT;

        -- Store booking reference if provided
        IF p_booking_ref IS NOT NULL THEN
            UPDATE escape_packages SET charter_reference = p_booking_ref WHERE id = p_package_id;
        END IF;

        -- Log alert
        INSERT INTO group_booking_alerts (package_id, alert_type, message)
        VALUES (p_package_id, 'reschedule_accepted',
                'Admin confirmed ' || v_participants || ' participants. Ref: ' || COALESCE(p_booking_ref, 'N/A'));

        RETURN jsonb_build_object(
            'success', true,
            'participants_confirmed', v_participants,
            'package', v_pkg.package_name,
            'booking_reference', p_booking_ref
        );
    END IF;

    -- ── DELAY ────────────────────────────────────────────────────
    IF p_action = 'delay' THEN
        INSERT INTO group_booking_alerts (package_id, alert_type, message)
        VALUES (p_package_id, 'delay', COALESCE(p_message, 'Trip delayed by admin'));

        RETURN jsonb_build_object(
            'success', true,
            'message', 'Delay alert broadcast',
            'detail', p_message
        );
    END IF;

    -- ── REFUND ALL ───────────────────────────────────────────────
    IF p_action = 'refund_all' THEN
        FOR v_rider_record IN
            SELECT id, rider_id, paid_cents
            FROM escape_group_participants
            WHERE package_id = p_package_id
              AND status IN ('confirmed', 'passport_pending', 'travel_ready', 'payment_pending', 'intent_pending')
        LOOP
            IF v_rider_record.paid_cents > 0 THEN
                PERFORM credit_wallet(
                    v_rider_record.rider_id,
                    v_rider_record.paid_cents,
                    'travel_package_refund',
                    'Full refund — trip cancelled by admin',
                    v_rider_record.id
                );
            END IF;

            UPDATE escape_group_participants
            SET status = CASE WHEN v_rider_record.paid_cents > 0 THEN 'refunded' ELSE 'cancelled' END
            WHERE id = v_rider_record.id;

            v_refunded := v_refunded + 1;
        END LOOP;

        INSERT INTO group_booking_alerts (package_id, alert_type, message)
        VALUES (p_package_id, 'refund_completed',
                'Admin refunded ' || v_refunded || ' participants for cancelled trip');

        RETURN jsonb_build_object('success', true, 'refunded', v_refunded);
    END IF;

    RETURN jsonb_build_object('success', false, 'error', 'Unhandled action');
END;
$$;


ALTER FUNCTION "public"."admin_escape_action"("p_package_id" "uuid", "p_action" "text", "p_booking_ref" "text", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_escape_action"("p_package_id" "uuid", "p_action" "text", "p_departure_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_arrival_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_booking_ref" "text" DEFAULT NULL::"text", "p_message" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "detail" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_pkg RECORD;
  v_participant RECORD;
  v_refunded INT := 0;
  v_notified INT := 0;
  v_itinerary_id UUID;
BEGIN
  -- Verify package exists
  SELECT id, package_name INTO v_pkg FROM public.escape_packages WHERE id = p_package_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false::BOOLEAN, 'Package not found'::TEXT;
    RETURN;
  END IF;

  IF p_action = 'confirm' THEN
    FOR v_participant IN
      SELECT p.id, p.rider_id, p.party_size, p.status, p.paid_cents
      FROM public.escape_group_participants p
      WHERE p.package_id = p_package_id AND p.status IN ('confirmed', 'payment_pending')
    LOOP
      IF v_participant.status = 'payment_pending' THEN
        UPDATE public.escape_group_participants
        SET status = 'confirmed', confirmed_at = now()
        WHERE id = v_participant.id;
      END IF;

      INSERT INTO public.passenger_details (participant_id, rider_id, full_name, date_of_birth, nationality)
      VALUES (v_participant.id, v_participant.rider_id, '', '2000-01-01', 'TT')
      ON CONFLICT (participant_id) DO NOTHING;

      UPDATE public.escape_group_participants
      SET status = 'passport_pending'
      WHERE id = v_participant.id;
    END LOOP;

    IF p_booking_ref IS NOT NULL THEN
      SELECT id INTO v_itinerary_id FROM public.master_escape_itineraries WHERE package_id = p_package_id LIMIT 1;
      IF FOUND THEN
        INSERT INTO public.itinerary_legs (master_itinerary_id, leg_sequence, service_type, status, reference_code, scheduled_start, scheduled_end)
        SELECT v_itinerary_id, 1, 'flight', 'confirmed', p_booking_ref, p_departure_date, p_arrival_date
        WHERE EXISTS (SELECT 1 FROM public.escape_group_participants WHERE package_id = p_package_id AND status = 'passport_pending');
      END IF;
    END IF;

    INSERT INTO public.group_booking_alerts (package_id, alert_type, message)
    VALUES (p_package_id, 'reschedule_accepted', 'Admin confirmed package. Ref: ' || COALESCE(p_booking_ref, 'N/A'));

    RETURN QUERY SELECT true::BOOLEAN, 'Confirmed'::TEXT;
    RETURN;
  END IF;

  IF p_action = 'delay' THEN
    INSERT INTO public.group_booking_alerts (package_id, alert_type, message)
    VALUES (p_package_id, 'delay', COALESCE(p_message, 'Trip delayed by admin'));
    RETURN QUERY SELECT true::BOOLEAN, 'Alert logged'::TEXT;
    RETURN;
  END IF;

  IF p_action = 'refund_all' THEN
    FOR v_participant IN
      SELECT p.id, p.rider_id, p.paid_cents
      FROM public.escape_group_participants p
      WHERE p.package_id = p_package_id AND p.status IN ('confirmed', 'passport_pending', 'travel_ready')
    LOOP
      IF v_participant.paid_cents > 0 THEN
        PERFORM public.credit_wallet(
          v_participant.rider_id,
          v_participant.paid_cents,
          'travel_package_refund',
          'Full refund — trip cancelled by admin',
          v_participant.id::TEXT
        );
        UPDATE public.escape_group_participants SET status = 'refunded' WHERE id = v_participant.id;
      ELSE
        UPDATE public.escape_group_participants SET status = 'cancelled' WHERE id = v_participant.id;
      END IF;
      v_refunded := v_refunded + 1;
    END LOOP;

    INSERT INTO public.group_booking_alerts (package_id, alert_type, message)
    VALUES (p_package_id, 'refund_completed', 'Admin refunded ' || v_refunded || ' participants');

    RETURN QUERY SELECT true::BOOLEAN, 'Refunded ' || v_refunded || ' participants';
    RETURN;
  END IF;

  RETURN QUERY SELECT false::BOOLEAN, 'Unknown action: ' || p_action;
END;
$$;


ALTER FUNCTION "public"."admin_escape_action"("p_package_id" "uuid", "p_action" "text", "p_departure_date" timestamp with time zone, "p_arrival_date" timestamp with time zone, "p_booking_ref" "text", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_band_revshare"("p_band_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "ride_id" "uuid", "band_id" "uuid", "event_id" "uuid", "rider_id" "uuid", "fare_cents" integer, "revshare_cents" integer, "status" "text", "created_at" timestamp with time zone, "rider_email" "text", "band_name" "text", "event_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  SELECT
    rl.id, rl.ride_id, rl.band_id, rl.event_id,
    rl.rider_id, rl.fare_cents, rl.revshare_cents,
    rl.status, rl.created_at,
    p.email AS rider_email,
    cb.name AS band_name,
    ce.name AS event_name
  FROM public.band_revshare_ledger rl
  LEFT JOIN public.profiles p ON p.id = rl.rider_id
  LEFT JOIN public.carnival_bands cb ON cb.id = rl.band_id
  LEFT JOIN public.carnival_events ce ON ce.id = rl.event_id
  WHERE (p_band_id IS NULL OR rl.band_id = p_band_id)
    AND (p_status IS NULL OR rl.status = p_status)
  ORDER BY rl.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."admin_get_band_revshare"("p_band_id" "uuid", "p_status" "text") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."carnival_bands" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "description" "text" DEFAULT ''::"text",
    "logo_url" "text" DEFAULT ''::"text",
    "contact_email" "text" DEFAULT ''::"text",
    "website_url" "text" DEFAULT ''::"text",
    "revshare_percent" integer DEFAULT 5 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
