CREATE OR REPLACE FUNCTION "public"."admin_get_pending_revshare"("p_ledger_type" "text" DEFAULT NULL::"text") RETURNS TABLE("ledger_type" "text", "organizer_id" "uuid", "organizer_name" "text", "pending_rides" bigint, "pending_cents" bigint, "oldest_pending" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Band ledger summary
  IF p_ledger_type IS NULL OR p_ledger_type = 'band' THEN
    RETURN QUERY
    SELECT
      'band'::TEXT AS ledger_type,
      brl.band_id AS organizer_id,
      cb.name AS organizer_name,
      COUNT(*)::BIGINT AS pending_rides,
      SUM(brl.revshare_cents)::BIGINT AS pending_cents,
      MIN(brl.created_at) AS oldest_pending
    FROM band_revshare_ledger brl
    JOIN carnival_bands cb ON cb.id = brl.band_id
    WHERE brl.status = 'pending'
    GROUP BY brl.band_id, cb.name
    ORDER BY pending_cents DESC;
  END IF;

  -- Event ledger summary
  IF p_ledger_type IS NULL OR p_ledger_type = 'event' THEN
    RETURN QUERY
    SELECT
      'event'::TEXT AS ledger_type,
      erl.organizer_id,
      eo.name AS organizer_name,
      COUNT(*)::BIGINT AS pending_rides,
      SUM(erl.revshare_cents)::BIGINT AS pending_cents,
      MIN(erl.created_at) AS oldest_pending
    FROM event_revshare_ledger erl
    JOIN event_organizers eo ON eo.id = erl.organizer_id
    WHERE erl.status = 'pending'
    GROUP BY erl.organizer_id, eo.name
    ORDER BY pending_cents DESC;
  END IF;
END;
$$;


ALTER FUNCTION "public"."admin_get_pending_revshare"("p_ledger_type" "text") OWNER TO "postgres";


