CREATE OR REPLACE FUNCTION "public"."admin_process_revshare_payout"("p_ledger_type" "text", "p_organizer_id" "uuid", "p_admin_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total_cents  INTEGER := 0;
  v_ride_count   INTEGER := 0;
  v_org_name     TEXT;
  v_payout_id    UUID;
BEGIN
  -- Validate ledger type
  IF p_ledger_type NOT IN ('band', 'event') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid ledger_type. Must be ''band'' or ''event''.');
  END IF;

  -- Lock and aggregate pending records per organizer
  IF p_ledger_type = 'band' THEN
    SELECT COALESCE(SUM(brl.revshare_cents), 0), COUNT(*)
    INTO v_total_cents, v_ride_count
    FROM band_revshare_ledger brl
    WHERE brl.band_id = p_organizer_id AND brl.status = 'pending'
    FOR UPDATE OF brl;

    SELECT cb.name INTO v_org_name FROM carnival_bands cb WHERE cb.id = p_organizer_id;
  ELSE
    SELECT COALESCE(SUM(erl.revshare_cents), 0), COUNT(*)
    INTO v_total_cents, v_ride_count
    FROM event_revshare_ledger erl
    WHERE erl.organizer_id = p_organizer_id AND erl.status = 'pending'
    FOR UPDATE OF erl;

    SELECT eo.name INTO v_org_name FROM event_organizers eo WHERE eo.id = p_organizer_id;
  END IF;

  IF v_ride_count = 0 OR v_total_cents <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No pending revshare records found for this organizer');
  END IF;

  -- Mark all pending records as paid
  IF p_ledger_type = 'band' THEN
    UPDATE band_revshare_ledger brl
    SET status = 'paid', updated_at = NOW()
    WHERE brl.band_id = p_organizer_id AND brl.status = 'pending';
  ELSE
    UPDATE event_revshare_ledger erl
    SET status = 'paid', updated_at = NOW()
    WHERE erl.organizer_id = p_organizer_id AND erl.status = 'pending';
  END IF;

  -- Insert payout audit record
  INSERT INTO revshare_payouts (ledger_type, organizer_id, organizer_name, total_cents, ride_count, status, processed_by)
  VALUES (p_ledger_type, p_organizer_id, COALESCE(v_org_name, 'Unknown'), v_total_cents, v_ride_count, 'completed', p_admin_id)
  RETURNING id INTO v_payout_id;

  RETURN jsonb_build_object(
    'success', true,
    'payout_id', v_payout_id,
    'total_cents', v_total_cents,
    'ride_count', v_ride_count,
    'organizer_name', v_org_name
  );
END;
$$;


ALTER FUNCTION "public"."admin_process_revshare_payout"("p_ledger_type" "text", "p_organizer_id" "uuid", "p_admin_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_rotate_merchant_key"("p_key_id" "uuid", "p_new_raw" "text", "p_new_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_merchant_id UUID;
    v_new_hash TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    SELECT merchant_id INTO v_merchant_id FROM public.merchant_api_keys WHERE id = p_key_id;
    IF v_merchant_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Key not found');
    END IF;

    -- Deactivate old
    UPDATE public.merchant_api_keys SET is_active = false WHERE id = p_key_id;

    -- Insert new
    v_new_hash := encode(digest(p_new_raw, 'sha256'), 'hex');
    INSERT INTO public.merchant_api_keys (merchant_id, key_hash, label, scopes, is_active)
    VALUES (v_merchant_id, v_new_hash, COALESCE(p_new_label, 'Rotated ' || now()::date), '{order:read}', true);

    RETURN jsonb_build_object('success', true, 'raw_key', p_new_raw, 'merchant_id', v_merchant_id);
END;
$$;


ALTER FUNCTION "public"."admin_rotate_merchant_key"("p_key_id" "uuid", "p_new_raw" "text", "p_new_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_pricing"("p_key" "text", "p_value_cents" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;
    IF p_value_cents < 0 THEN RAISE EXCEPTION 'value_cents must be >= 0'; END IF;
    INSERT INTO public.pricing_config (key, value_cents, updated_at)
    VALUES (p_key, p_value_cents, now())
    ON CONFLICT (key) DO UPDATE SET value_cents = EXCLUDED.value_cents, updated_at = now();
END;
$$;


ALTER FUNCTION "public"."admin_set_pricing"("p_key" "text", "p_value_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_surge_zone"("p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision, "p_multiplier" numeric, "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO pricing_zones (
        name, center_lat, center_lng, radius_km,
        surge_multiplier, is_active, expires_at, created_at
    ) VALUES (
        format('Auto surge %.1fx @ %s,%s', p_multiplier, round(p_lat::numeric,4), round(p_lng::numeric,4)),
        p_lat, p_lng, p_radius_km,
        p_multiplier, true,
        COALESCE(p_expires_at, now() + interval '2 hours'),
        now()
    )
    ON CONFLICT (name) DO UPDATE
        SET surge_multiplier = EXCLUDED.surge_multiplier,
            is_active = true,
            expires_at = EXCLUDED.expires_at
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."admin_set_surge_zone"("p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision, "p_multiplier" numeric, "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_toggle_carnival_flag"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_active BOOLEAN;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  UPDATE public.system_feature_flags
  SET is_active = NOT is_active, updated_at = now()
  WHERE id = 'carnival_active'
  RETURNING is_active INTO v_active;

  RETURN v_active;
END;
$$;


