CREATE OR REPLACE FUNCTION "public"."admin_update_revshare_wipay_status"("p_payout_id" "uuid", "p_wipay_status" "text", "p_wipay_transaction_id" "text" DEFAULT NULL::"text", "p_wipay_error" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_wipay_status NOT IN ('pending', 'submitted', 'completed', 'failed') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid wipay_status');
  END IF;

  UPDATE revshare_payouts
  SET
    wipay_status = p_wipay_status,
    wipay_transaction_id = COALESCE(p_wipay_transaction_id, wipay_transaction_id),
    wipay_error = COALESCE(p_wipay_error, wipay_error)
  WHERE id = p_payout_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


