CREATE OR REPLACE FUNCTION "public"."admin_update_ride_status"("p_ride_id" "uuid", "p_status" "text", "p_driver_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF auth.uid() IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Only admins can update ride status';
    END IF;

    UPDATE public.rides
    SET
        status = p_status::public.ride_status,
        driver_id = COALESCE(p_driver_id, driver_id),
        updated_at = NOW()
    WHERE id = p_ride_id;

    RETURN FOUND;
END;
$$;


