CREATE OR REPLACE FUNCTION "public"."admin_upsert_escape_package"("p_id" "uuid" DEFAULT NULL::"uuid", "p_flight_block_id" "uuid" DEFAULT NULL::"uuid", "p_lodging_node_id" "uuid" DEFAULT NULL::"uuid", "p_package_name" "text" DEFAULT NULL::"text", "p_tagline" "text" DEFAULT NULL::"text", "p_cover_image_url" "text" DEFAULT NULL::"text", "p_price_per_person_cents" integer DEFAULT NULL::integer, "p_flight_cost_per_person_cents" integer DEFAULT NULL::integer, "p_lodging_cost_per_person_cents" integer DEFAULT NULL::integer, "p_driver_origin_zone" "text" DEFAULT NULL::"text", "p_driver_origin_cost_cents" integer DEFAULT NULL::integer, "p_driver_destination_zone" "text" DEFAULT NULL::"text", "p_driver_destination_cost_cents" integer DEFAULT NULL::integer, "p_platform_margin_cents" integer DEFAULT NULL::integer, "p_loyalty_rebate_cents" integer DEFAULT NULL::integer, "p_is_active" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_id UUID;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;

    IF p_id IS NOT NULL THEN
        UPDATE public.escape_packages SET
            flight_block_id               = COALESCE(p_flight_block_id, flight_block_id),
            lodging_node_id               = COALESCE(p_lodging_node_id, lodging_node_id),
            package_name                  = COALESCE(p_package_name, package_name),
            tagline                       = COALESCE(p_tagline, tagline),
            cover_image_url               = COALESCE(p_cover_image_url, cover_image_url),
            price_per_person_cents        = COALESCE(p_price_per_person_cents, price_per_person_cents),
            flight_cost_per_person_cents  = COALESCE(p_flight_cost_per_person_cents, flight_cost_per_person_cents),
            lodging_cost_per_person_cents = COALESCE(p_lodging_cost_per_person_cents, lodging_cost_per_person_cents),
            driver_origin_zone            = COALESCE(p_driver_origin_zone, driver_origin_zone),
            driver_origin_cost_cents      = COALESCE(p_driver_origin_cost_cents, driver_origin_cost_cents),
            driver_destination_zone       = COALESCE(p_driver_destination_zone, driver_destination_zone),
            driver_destination_cost_cents = COALESCE(p_driver_destination_cost_cents, driver_destination_cost_cents),
            platform_margin_cents         = COALESCE(p_platform_margin_cents, platform_margin_cents),
            loyalty_rebate_cents          = COALESCE(p_loyalty_rebate_cents, loyalty_rebate_cents),
            is_active                     = COALESCE(p_is_active, is_active),
            updated_at = now()
        WHERE id = p_id RETURNING id INTO v_id;
    ELSE
        INSERT INTO public.escape_packages (
            flight_block_id, lodging_node_id, package_name, tagline, cover_image_url,
            price_per_person_cents, flight_cost_per_person_cents, lodging_cost_per_person_cents,
            driver_origin_zone, driver_origin_cost_cents,
            driver_destination_zone, driver_destination_cost_cents,
            platform_margin_cents, loyalty_rebate_cents, is_active, created_by
        ) VALUES (
            p_flight_block_id, p_lodging_node_id, p_package_name, p_tagline, p_cover_image_url,
            p_price_per_person_cents, p_flight_cost_per_person_cents, p_lodging_cost_per_person_cents,
            p_driver_origin_zone, COALESCE(p_driver_origin_cost_cents, 0),
            p_driver_destination_zone, COALESCE(p_driver_destination_cost_cents, 0),
            p_platform_margin_cents, COALESCE(p_loyalty_rebate_cents, 0), p_is_active, auth.uid()
        ) RETURNING id INTO v_id;
    END IF;

    RETURN v_id;
END;
$$;


