CREATE OR REPLACE FUNCTION "public"."auto_payout_scout_referral"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_driver_user_id UUID;
  v_wallet_id UUID;
BEGIN
  IF NEW.status <> 'qualified' OR OLD.status = 'qualified' THEN RETURN NEW; END IF;
  SELECT user_id INTO v_driver_user_id FROM drivers WHERE id = NEW.driver_id;
  IF v_driver_user_id IS NULL THEN RETURN NEW; END IF;
  SELECT id INTO v_wallet_id FROM wallets WHERE user_id = v_driver_user_id;
  IF v_wallet_id IS NULL THEN
    INSERT INTO wallets (user_id, balance_cents) VALUES (v_driver_user_id, NEW.payout_amount_cents);
  ELSE
    UPDATE wallets SET balance_cents = balance_cents + NEW.payout_amount_cents WHERE id = v_wallet_id;
  END IF;
  INSERT INTO wallet_transactions (user_id, amount, transaction_type, description, status, reference_id)
  VALUES (v_driver_user_id, NEW.payout_amount_cents, 'scout_referral_payout',
    FORMAT('Scout referral payout: %s qualified', COALESCE(NEW.property_name, 'Property lead')),
    'completed', NEW.id::TEXT)
  RETURNING id INTO NEW.wallet_txn_id;
  NEW.status := 'paid';
  RETURN NEW;
END;
$$;


