CREATE OR REPLACE FUNCTION "public"."auto_succeed_commander"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_successor record;
  v_territory_name text;
BEGIN
  SELECT name INTO v_territory_name FROM territories WHERE id = OLD.territory_id;

  SELECT ts.* INTO v_successor
  FROM territory_successors ts
  WHERE ts.territory_id = OLD.territory_id
    AND ts.is_active = true
    AND ts.status IN ('confirmed', 'pending')
  ORDER BY ts.priority ASC
  LIMIT 1;

  IF FOUND THEN
    INSERT INTO pod_commanders (user_id, territory_id, status, metrics)
    VALUES (v_successor.successor_id, OLD.territory_id, 'active', '{}'::jsonb)
    ON CONFLICT (user_id) DO UPDATE
      SET territory_id = OLD.territory_id, status = 'active', updated_at = now();

    UPDATE territories
    SET commander_id = v_successor.successor_id,
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'last_succession', jsonb_build_object(
            'from', OLD.user_id,
            'to', v_successor.successor_id,
            'triggered_at', now()::text
          )
        )
    WHERE id = OLD.territory_id;

    UPDATE territory_successors
    SET status = 'activated', confirmed_at = now()
    WHERE id = v_successor.id;

    UPDATE profiles SET role = 'pod_commander'::user_role WHERE id = v_successor.successor_id;

    INSERT INTO system_alerts (type, severity, title, details)
    VALUES (
      'commander_succession', 'info',
      'Territory auto-succeeded: ' || COALESCE(v_territory_name, 'unknown'),
      jsonb_build_object(
        'territory_id', OLD.territory_id,
        'previous_commander', OLD.user_id,
        'new_commander', v_successor.successor_id,
        'successor_priority', v_successor.priority
      )
    );
  ELSE
    UPDATE territories SET commander_id = NULL WHERE id = OLD.territory_id;

    INSERT INTO system_alerts (type, severity, title, details)
    VALUES (
      'commander_orphaned', 'warning',
      'Territory orphaned: ' || COALESCE(v_territory_name, 'unknown'),
      jsonb_build_object(
        'territory_id', OLD.territory_id,
        'previous_commander', OLD.user_id
      )
    );
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."auto_succeed_commander"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."book_travel_atomic"("p_user_id" "uuid", "p_package_id" "uuid", "p_traveler_count" integer, "p_payment_method" "text", "p_passenger_names" "text" DEFAULT '[]'::"text", "p_special_requests" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_package        travel_packages%ROWTYPE;
    v_wallet_balance BIGINT;
    v_total_cents    INTEGER;
    v_margin_cents   INTEGER;
    v_booking_id     UUID;
    v_wallet_txn_id  UUID;
BEGIN
    -- Lock the package row exclusively
    SELECT * INTO v_package
    FROM travel_packages
    WHERE id = p_package_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Package not found';
    END IF;

    IF v_package.status <> 'active' THEN
        RAISE EXCEPTION 'Package is not available (status: %)', v_package.status;
    END IF;

    IF v_package.travelers_booked + p_traveler_count > v_package.max_travelers THEN
        RAISE EXCEPTION 'sold_out: only % seats remain',
            v_package.max_travelers - v_package.travelers_booked;
    END IF;

    v_total_cents  := v_package.price_per_person_cents * p_traveler_count;
    v_margin_cents := (v_package.price_per_person_cents - v_package.wholesale_cost_cents) * p_traveler_count;

    -- Wallet payment: deduct balance
    IF p_payment_method = 'wallet' THEN
        SELECT balance_cents INTO v_wallet_balance
        FROM wallets
        WHERE user_id = p_user_id
        FOR UPDATE;

        IF v_wallet_balance IS NULL THEN
            RAISE EXCEPTION 'No wallet found for user';
        END IF;

        IF v_wallet_balance < v_total_cents THEN
            RAISE EXCEPTION 'insufficient_balance: need % have %', v_total_cents, v_wallet_balance;
        END IF;

        UPDATE wallets
        SET balance_cents = balance_cents - v_total_cents,
            updated_at    = now()
        WHERE user_id = p_user_id;

        INSERT INTO wallet_transactions (
            user_id, amount, transaction_type, description, status, metadata
        ) VALUES (
            p_user_id,
            -v_total_cents,
            'travel_package_payment',
            format('Caribbean package — %s × %s traveler(s)', v_package.title, p_traveler_count),
            'completed',
            jsonb_build_object('package_id', p_package_id, 'traveler_count', p_traveler_count)
        ) RETURNING id INTO v_wallet_txn_id;
    END IF;

    -- Reserve seats
    UPDATE travel_packages
    SET travelers_booked = travelers_booked + p_traveler_count,
        status = CASE
            WHEN travelers_booked + p_traveler_count >= max_travelers THEN 'sold_out'
            ELSE status
        END,
        updated_at = now()
    WHERE id = p_package_id;

    -- Also reserve flight seats if linked
    IF v_package.flight_inventory_id IS NOT NULL THEN
        UPDATE flight_inventory
        SET seats_reserved = seats_reserved + p_traveler_count,
            status = CASE
                WHEN seats_reserved + p_traveler_count >= seats_total THEN 'sold_out'
                ELSE status
            END
        WHERE id = v_package.flight_inventory_id;
    END IF;

    -- Create booking record
    INSERT INTO travel_bookings (
        package_id, user_id, flight_inventory_id, traveler_count,
        total_cents, platform_margin_cents, status, payment_method,
        wallet_transaction_id, passenger_names, special_requests, confirmed_at
    ) VALUES (
        p_package_id, p_user_id, v_package.flight_inventory_id, p_traveler_count,
        v_total_cents, v_margin_cents,
        CASE WHEN p_payment_method = 'wallet' THEN 'confirmed' ELSE 'pending' END,
        p_payment_method,
        v_wallet_txn_id, p_passenger_names::jsonb, p_special_requests,
        CASE WHEN p_payment_method = 'wallet' THEN now() ELSE NULL END
    ) RETURNING id INTO v_booking_id;

    RETURN jsonb_build_object(
        'booking_id',               v_booking_id,
        'package_title',            v_package.title,
        'total_cents',              v_total_cents,
        'platform_margin_cents',    v_margin_cents,
        'margin_pct',               round(((v_package.price_per_person_cents - v_package.wholesale_cost_cents)::numeric / v_package.price_per_person_cents) * 100, 1),
        'includes_airport_transfer',v_package.includes_airport_transfer,
        'departure_at',             v_package.departure_at
    );
END;
$$;


ALTER FUNCTION "public"."book_travel_atomic"("p_user_id" "uuid", "p_package_id" "uuid", "p_traveler_count" integer, "p_payment_method" "text", "p_passenger_names" "text", "p_special_requests" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_fare_split"("fare_cents" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_platform_fee bigint;
    v_reserve_fee  bigint;
    v_driver_share bigint;
BEGIN
    IF fare_cents IS NULL OR fare_cents <= 0 THEN
        RETURN jsonb_build_object(
            'gross_cents',         0,
            'driver_share_cents',  0,
            'platform_fee_cents',  0,
            'reserve_fee_cents',   0
        );
    END IF;

    v_platform_fee := ROUND(fare_cents * 0.15);
    v_reserve_fee  := ROUND(fare_cents * 0.03);
    v_driver_share := fare_cents - v_platform_fee - v_reserve_fee;

    RETURN jsonb_build_object(
        'gross_cents',         fare_cents,
        'driver_share_cents',  v_driver_share,
        'platform_fee_cents',  v_platform_fee,
        'reserve_fee_cents',   v_reserve_fee
    );
END;
$$;


ALTER FUNCTION "public"."calculate_fare_split"("fare_cents" bigint) OWNER TO "postgres";


