CREATE OR REPLACE FUNCTION "public"."calculate_settlement"("p_gross_cents" integer) RETURNS TABLE("reserve_cents" integer, "platform_fee_cents" integer, "driver_payout_cents" integer)
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_reserve   INTEGER;
    v_platform  INTEGER;
    v_plat_cents INTEGER;
    v_rate      NUMERIC;
BEGIN
    v_reserve := ROUND(p_gross_cents * 0.015);

    SELECT value_cents INTO v_plat_cents
    FROM public.pricing_config
    WHERE key = 'PLATFORM_RATE_CENTS';
    v_rate := COALESCE(v_plat_cents, 1900) / 10000.0;

    v_platform := ROUND(p_gross_cents * v_rate);

    RETURN QUERY SELECT
        v_reserve,
        v_platform,
        (p_gross_cents - v_platform)::INTEGER;
END;
$$;


ALTER FUNCTION "public"."calculate_settlement"("p_gross_cents" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_settlement"("p_gross_cents" integer) IS 'Uniform settlement math used by ALL payment paths:
     reserve = round(gross * 0.015)
     net = gross - reserve
     platform_fee = round(net * 0.185)
     driver_payout = net - platform_fee
     Invariant: reserve + platform_fee + driver_payout = gross';



CREATE OR REPLACE FUNCTION "public"."calculate_subscription_discount"("p_user_id" "uuid", "p_base_fare_cents" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_tier          rider_subscription_tier;
    v_level         SMALLINT;
    v_level_discount INTEGER := 0;
    v_is_g_member   BOOLEAN := false;
    v_discount_cents INTEGER;
BEGIN
    SELECT subscription_tier INTO v_tier
    FROM profiles
    WHERE id = p_user_id;
    v_is_g_member := (v_tier = 'g_member');

    SELECT level INTO v_level
    FROM rider_progression
    WHERE rider_id = p_user_id;

    IF v_level IS NOT NULL AND v_level >= 2 THEN
        SELECT discount_percent INTO v_level_discount
        FROM progression_config
        WHERE level = v_level;
        v_level_discount := COALESCE(v_level_discount, 0);
    END IF;

    IF v_is_g_member THEN
        v_level_discount := GREATEST(15, v_level_discount + 3);
    END IF;

    v_discount_cents := (p_base_fare_cents * v_level_discount / 100);
    RETURN LEAST(v_discount_cents, 5000);
END;
$$;


ALTER FUNCTION "public"."calculate_subscription_discount"("p_user_id" "uuid", "p_base_fare_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_escape_wallet_payment"("p_reservation_id" "uuid", "p_rider_id" "uuid") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_total_cents    INTEGER;
    v_wallet_id      UUID;
    v_wallet_balance INTEGER;
BEGIN
    -- Lock reservation
    SELECT total_price_cents INTO v_total_cents
    FROM public.package_reservations
    WHERE id = p_reservation_id AND rider_id = p_rider_id AND status = 'ACTIVE_HOLD'
    FOR UPDATE;

    IF NOT FOUND THEN
        success := FALSE; message := 'Reservation not found or not in ACTIVE_HOLD status.';
        RETURN NEXT; RETURN;
    END IF;

    -- Lock wallet
    SELECT id, balance_cents INTO v_wallet_id, v_wallet_balance
    FROM public.wallets
    WHERE user_id = p_rider_id
    FOR UPDATE;

    IF NOT FOUND OR v_wallet_balance < v_total_cents THEN
        success := FALSE;
        message := 'Insufficient wallet balance. Need TTD ' || ROUND(v_total_cents::NUMERIC / 100, 2)::TEXT;
        RETURN NEXT; RETURN;
    END IF;

    -- Deduct
    UPDATE public.wallets
    SET balance_cents = balance_cents - v_total_cents,
        updated_at = now()
    WHERE id = v_wallet_id;

    -- Log
    INSERT INTO public.wallet_transactions (
        user_id, amount_cents, transaction_type, description, metadata
    ) VALUES (
        p_rider_id, -v_total_cents, 'travel_package_payment',
        'G-Escape booking — wallet capture',
        jsonb_build_object('reservation_id', p_reservation_id, 'source', 'g_escape')
    );

    -- Advance reservation state
    UPDATE public.package_reservations
    SET status = 'CAPTURED', captured_at = now(), updated_at = now()
    WHERE id = p_reservation_id;

    success := TRUE; message := 'Payment captured.';
    RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."capture_escape_wallet_payment"("p_reservation_id" "uuid", "p_rider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charge_escape_participant_wallet"("p_rider_id" "uuid", "p_amount_cents" integer, "p_package_name" "text", "p_reference_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_wallet_balance INTEGER;
    v_reserve INTEGER;
    v_platform INTEGER;
    v_idempotent TEXT;
BEGIN
    v_idempotent := 'escape_' || p_reference_id::text;
    v_reserve := ROUND(p_amount_cents * 0.015);
    v_platform := ROUND((p_amount_cents - v_reserve) * 0.185);
    
    SELECT balance_cents INTO v_wallet_balance
    FROM public.wallets
    WHERE user_id = p_rider_id
    FOR UPDATE;

    IF v_wallet_balance IS NULL OR v_wallet_balance < p_amount_cents THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient wallet balance');
    END IF;

    UPDATE public.wallets
    SET balance_cents = balance_cents - p_amount_cents
    WHERE user_id = p_rider_id;

    INSERT INTO public.wallet_transactions (user_id, amount, transaction_type, description, status, reference_id)
    VALUES (p_rider_id, -p_amount_cents, 'escape_group_payment',
            'Escape group: ' || p_package_name, 'completed', v_idempotent);

    INSERT INTO public.wallet_transactions (user_id, amount, transaction_type, description, status, reference_id)
    VALUES (p_rider_id, v_platform, 'escape_platform_fee',
            'Platform fee: ' || p_package_name, 'completed', v_idempotent || '_fee');

    RETURN jsonb_build_object('success', true, 'amount_cents', p_amount_cents);
END;
$$;


ALTER FUNCTION "public"."charge_escape_participant_wallet"("p_rider_id" "uuid", "p_amount_cents" integer, "p_package_name" "text", "p_reference_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_driver_debt_limit"("p_driver_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_total_owed INTEGER;
BEGIN
    SELECT COALESCE(SUM(amount), 0) INTO v_total_owed
    FROM public.wallet_transactions
    WHERE user_id = p_driver_id
      AND transaction_type = 'commission_debt'
      AND status = 'pending';

    RETURN v_total_owed > -30000;
END;
$$;


ALTER FUNCTION "public"."check_driver_debt_limit"("p_driver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_driver_referral_commission"("p_driver_user_id" "uuid", "p_ride_id" "uuid", "p_platform_fee_cents" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_referrer_id UUID;
    v_commission INTEGER;
BEGIN
    SELECT referrer_id INTO v_referrer_id
    FROM referral_earnings
    WHERE referee_id = p_driver_user_id
      AND type = 'driver'
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > now())
    LIMIT 1;

    IF NOT FOUND THEN RETURN 0; END IF;

    v_commission := GREATEST(1, floor(p_platform_fee_cents * 0.01));

    INSERT INTO wallet_transactions (user_id, ride_id, amount, transaction_type, description, status)
    VALUES (v_referrer_id, p_ride_id, v_commission, 'bonus',
            'Driver referral commission (1% of platform fee)', 'completed');

    RETURN v_commission;
END;
$$;


ALTER FUNCTION "public"."check_driver_referral_commission"("p_driver_user_id" "uuid", "p_ride_id" "uuid", "p_platform_fee_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_equity_vesting_on_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_property_id UUID;
    v_contract_id UUID;
BEGIN
    IF NEW.status <> 'confirmed' OR OLD.status = 'confirmed' THEN
        RETURN NEW;
    END IF;

    SELECT tp.property_id INTO v_property_id
    FROM travel_packages tp
    WHERE tp.id = NEW.package_id;

    IF v_property_id IS NULL THEN RETURN NEW; END IF;

    SELECT id INTO v_contract_id
    FROM equity_contracts
    WHERE property_id = v_property_id
      AND status IN ('signed', 'active')
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_contract_id IS NULL THEN RETURN NEW; END IF;

    UPDATE equity_contracts
    SET current_room_nights_delivered = current_room_nights_delivered + NEW.traveler_count,
        current_equity_pct = CASE
            WHEN current_room_nights_delivered + NEW.traveler_count >= tier_2_rooms THEN tier_2_equity_pct
            WHEN current_room_nights_delivered + NEW.traveler_count >= tier_1_rooms THEN tier_1_equity_pct
            ELSE current_equity_pct
        END,
        status = CASE
            WHEN status = 'signed' THEN 'active'
            ELSE status
        END,
        updated_at = now()
    WHERE id = v_contract_id;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_equity_vesting_on_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_flight_tipping_points"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_block    RECORD;
    v_res      RECORD;
    v_itin_id  UUID;
    v_arrive   TIMESTAMPTZ;
BEGIN
    FOR v_block IN
        SELECT id, tipping_point_seats, allocated_seats,
               departure_time, outbound_arrival_time, return_time
        FROM public.flight_blocks
        WHERE status = 'POOLING' AND cancel_deadline <= now()
        FOR UPDATE
    LOOP
        IF v_block.allocated_seats >= v_block.tipping_point_seats THEN
            -- CONFIRM the flight block
            UPDATE public.flight_blocks
            SET status = 'CONFIRMED', confirmed_at = now(), updated_at = now()
            WHERE id = v_block.id;

            -- For each CAPTURED reservation, build the itinerary and write the ledger
            FOR v_res IN
                SELECT pr.id AS reservation_id, pr.rider_id, pr.escape_package_id,
                       pr.total_price_cents, pr.guest_count,
                       pr.pickup_lat, pr.pickup_lng,
                       ep.flight_cost_per_person_cents,
                       ep.lodging_cost_per_person_cents,
                       ep.driver_origin_cost_cents,
                       ep.driver_destination_cost_cents,
                       ep.platform_margin_cents,
                       ep.lodging_node_id
                FROM public.package_reservations pr
                JOIN public.escape_packages ep ON ep.id = pr.escape_package_id
                WHERE pr.flight_block_id = v_block.id AND pr.status = 'CAPTURED'
            LOOP
                UPDATE public.package_reservations
                SET status = 'CONFIRMED', confirmed_at = now(), updated_at = now()
                WHERE id = v_res.reservation_id;

                -- Estimated outbound arrival (45-min airbridge default if not set)
                v_arrive := COALESCE(
                    v_block.outbound_arrival_time,
                    v_block.departure_time + INTERVAL '45 minutes'
                );

                -- Create master itinerary (idempotent: ON CONFLICT updates timestamp)
                INSERT INTO public.master_escape_itineraries (
                    reservation_id, rider_id, package_id, flight_block_id,
                    total_paid_ttd, status
                ) VALUES (
                    v_res.reservation_id, v_res.rider_id, v_res.escape_package_id,
                    v_block.id,
                    ROUND(v_res.total_price_cents::NUMERIC / 100, 2),
                    'CONFIRMED'
                )
                ON CONFLICT (reservation_id) DO UPDATE SET updated_at = now()
                RETURNING id INTO v_itin_id;

                -- 4-leg journey (idempotent on conflict)
                INSERT INTO public.itinerary_legs (
                    master_itinerary_id, leg_sequence, service_type, status,
                    scheduled_start, scheduled_end, reference_code,
                    pickup_lat, pickup_lng
                ) VALUES
                    -- Leg 1: Trinidad home → Piarco (depart 3h before flight)
                    (v_itin_id, 1, 'GROUND_TRANSIT', 'scheduled',
                     v_block.departure_time - INTERVAL '3 hours',
                     v_block.departure_time - INTERVAL '1 hour',
                     'TT_AIRPORT_TRANSFER',
                     v_res.pickup_lat, v_res.pickup_lng),
                    -- Leg 2: Flight POS → destination
                    (v_itin_id, 2, 'AVIATION', 'scheduled',
                     v_block.departure_time, v_arrive, NULL, NULL, NULL),
                    -- Leg 3: Destination airport → villa (departs on flight arrival)
                    (v_itin_id, 3, 'GROUND_TRANSIT', 'scheduled',
                     v_arrive, v_arrive + INTERVAL '45 minutes',
                     'DEST_VILLA_TRANSFER', NULL, NULL),
                    -- Leg 4: Villa stay
                    (v_itin_id, 4, 'LODGING', 'scheduled',
                     v_arrive + INTERVAL '45 minutes',
                     COALESCE(v_block.return_time, v_block.departure_time + INTERVAL '48 hours'),
                     'VILLA_STAY', NULL, NULL)
                ON CONFLICT (master_itinerary_id, leg_sequence) DO NOTHING;

                -- Double-entry financial ledger (each booking flows escrow → vendors)
                -- Ground costs are fixed per-car (one vehicle per reservation group)
                -- Flight and lodging scale per-person
                INSERT INTO public.transit_financial_ledger (
                    reservation_id, source_party, destination_party, amount_ttd, reference_node_id
                ) VALUES
                    (v_res.reservation_id, 'escrow', 'airline_block',
                     ROUND((v_res.flight_cost_per_person_cents * v_res.guest_count)::NUMERIC / 100, 2),
                     v_block.id::TEXT),
                    (v_res.reservation_id, 'escrow', 'trinidad_driver',
                     ROUND(v_res.driver_origin_cost_cents::NUMERIC / 100, 2), NULL),
                    (v_res.reservation_id, 'escrow', 'tobago_driver',
                     ROUND(v_res.driver_destination_cost_cents::NUMERIC / 100, 2), NULL),
                    (v_res.reservation_id, 'escrow', 'villa_merchant',
                     ROUND((v_res.lodging_cost_per_person_cents * v_res.guest_count)::NUMERIC / 100, 2),
                     v_res.lodging_node_id::TEXT),
                    (v_res.reservation_id, 'escrow', 'platform_profit',
                     ROUND((v_res.platform_margin_cents * v_res.guest_count)::NUMERIC / 100, 2), NULL);
            END LOOP;

        ELSE
            -- Cancel: return all seats and guest allocations
            UPDATE public.flight_blocks
            SET status = 'CANCELLED', allocated_seats = 0, updated_at = now()
            WHERE id = v_block.id;

            UPDATE public.escape_packages
            SET allocated_guests = 0, updated_at = now()
            WHERE flight_block_id = v_block.id;

            UPDATE public.package_reservations
            SET status = 'CANCELLED', updated_at = now()
            WHERE flight_block_id = v_block.id AND status IN ('ACTIVE_HOLD','CAPTURED');
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."check_flight_tipping_points"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_global_debt_blocking"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    v_balance INTEGER;
BEGIN
    SELECT COALESCE(SUM(amount), 0) INTO v_balance
    FROM public.wallet_transactions
    WHERE user_id = NEW.rider_id;

    IF v_balance < -30000 THEN
        RAISE EXCEPTION 'GLOBAL_DEBT_BLOCK: Account suspended due to outstanding balance ($%). Settle to resume.', (v_balance::float / 100.0);
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."check_global_debt_blocking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_payment_completion_safety"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.status = 'completed' AND OLD.status != 'completed' THEN

        IF NEW.total_fare_cents IS NULL OR NEW.total_fare_cents = 0 THEN
            RETURN NEW;
        END IF;

        IF NEW.payment_method = 'cash' THEN
            IF NEW.cash_confirmed IS NOT TRUE THEN
                RAISE EXCEPTION 'Ride cannot complete without valid payment confirmation (Cash not confirmed)';
            END IF;
        ELSIF NEW.payment_method IN ('card', 'wipay') THEN
            IF NEW.payment_status != 'captured' THEN
                 RAISE EXCEPTION 'Ride cannot complete without valid payment confirmation (% not captured)', NEW.payment_method;
            END IF;
        ELSIF NEW.payment_method IN ('wallet', 'mixed') THEN
             IF NEW.payment_status NOT IN ('captured', 'confirmed') THEN
                 RAISE EXCEPTION 'Ride cannot complete without valid payment confirmation';
             END IF;
        END IF;

    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_payment_completion_safety"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_endpoint" "text", "p_max_requests" integer, "p_window_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_window_start TIMESTAMPTZ;
    v_count INTEGER;
BEGIN
    -- Round down to the start of the current window
    v_window_start := date_trunc('second', NOW()) - 
        ((EXTRACT(EPOCH FROM NOW())::INTEGER % p_window_seconds) * INTERVAL '1 second');

    -- Upsert: increment counter for this user/endpoint/window
    INSERT INTO public.rate_limit_log (user_id, endpoint, window_start, request_count)
    VALUES (p_user_id, p_endpoint, v_window_start, 1)
    ON CONFLICT (user_id, endpoint, window_start)
    DO UPDATE SET request_count = rate_limit_log.request_count + 1
    RETURNING request_count INTO v_count;

    -- Return TRUE if within limit, FALSE if exceeded
    RETURN v_count <= p_max_requests;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_endpoint" "text", "p_max_requests" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_available_driver"("p_pickup_lat" double precision, "p_pickup_lng" double precision, "p_vehicle_type" "text", "p_rider_id" "uuid", "p_max_distance_km" double precision DEFAULT 15, "p_candidate_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("driver_id" "uuid", "driver_name" "text", "distance_km" double precision, "composite_score" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  WEIGHT_DISTANCE CONSTANT float := 0.70;
  WEIGHT_ACCEPT   CONSTANT float := 0.30;
  v_driver_id uuid;
BEGIN
  -- Pick highest-scoring eligible driver. LEAST(1.0, ...) guards acos() domain
  -- (a driver exactly at pickup can produce a value marginally above 1.0).
  WITH candidates AS (
    SELECT
      d.id,
      6371 * acos(LEAST(1.0,
        cos(radians(p_pickup_lat)) * cos(radians(d.lat)) *
        cos(radians(d.lng) - radians(p_pickup_lng)) +
        sin(radians(p_pickup_lat)) * sin(radians(d.lat))
      )) AS dist_km,
      COALESCE(d.acceptance_rate, 0.80) AS acc
    FROM drivers d
    WHERE d.is_online = true
      AND d.is_verified = true
      AND d.active_ride_id IS NULL
      AND (p_candidate_ids IS NULL OR d.id = ANY(p_candidate_ids))
      AND (p_vehicle_type = 'Any' OR d.vehicle_type = p_vehicle_type)
      AND NOT EXISTS (
        SELECT 1 FROM blacklists b
        WHERE (b.user_id = p_rider_id AND b.blocked_user_id = d.user_id)
           OR (b.user_id = d.user_id AND b.blocked_user_id = p_rider_id)
      )
  )
  SELECT c.id INTO v_driver_id
  FROM candidates c
  WHERE (p_candidate_ids IS NOT NULL) OR (c.dist_km <= p_max_distance_km)
  ORDER BY (
    WEIGHT_DISTANCE * (1.0 - LEAST(c.dist_km / NULLIF(p_max_distance_km, 0), 1.0)) +
    WEIGHT_ACCEPT   * c.acc
  ) DESC
  LIMIT 1;

  IF v_driver_id IS NULL THEN
    RETURN;
  END IF;

  -- Atomically lock the chosen driver; if another dispatch already holds the
  -- lock, skip (caller re-queues) — eliminates double-dispatch.
  PERFORM 1 FROM drivers WHERE id = v_driver_id FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    d.id,
    d.name,
    6371 * acos(LEAST(1.0,
      cos(radians(p_pickup_lat)) * cos(radians(d.lat)) *
      cos(radians(d.lng) - radians(p_pickup_lng)) +
      sin(radians(p_pickup_lat)) * sin(radians(d.lat))
    )) AS distance_km,
    WEIGHT_DISTANCE * (1.0 - LEAST(
      (6371 * acos(LEAST(1.0,
        cos(radians(p_pickup_lat)) * cos(radians(d.lat)) *
        cos(radians(d.lng) - radians(p_pickup_lng)) +
        sin(radians(p_pickup_lat)) * sin(radians(d.lat))
      ))) / NULLIF(p_max_distance_km, 0), 1.0)) +
    WEIGHT_ACCEPT * COALESCE(d.acceptance_rate, 0.80) AS composite_score
  FROM drivers d WHERE d.id = v_driver_id;
END;
$$;


ALTER FUNCTION "public"."claim_available_driver"("p_pickup_lat" double precision, "p_pickup_lng" double precision, "p_vehicle_type" "text", "p_rider_id" "uuid", "p_max_distance_km" double precision, "p_candidate_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_driver_locations"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    DELETE FROM public.driver_locations
    WHERE created_at < NOW() - INTERVAL '24 hours'
    AND ride_id IS NULL;

    DELETE FROM public.driver_locations
    WHERE created_at < NOW() - INTERVAL '90 days';
END;
$$;


ALTER FUNCTION "public"."cleanup_driver_locations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_ghost_rides"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ride RECORD;
BEGIN
    FOR v_ride IN 
        SELECT id, rider_id 
        FROM public.rides 
        WHERE status IN ('requested', 'searching')
        AND created_at < NOW() - INTERVAL '3 minutes'
    LOOP
        UPDATE public.rides SET status = 'cancelled', updated_at = NOW() WHERE id = v_ride.id;
        INSERT INTO public.ride_events (ride_id, event_type, metadata)
        VALUES (v_ride.id, 'ai_retry_trigger', jsonb_build_object('reason', 'timeout'));
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."cleanup_ghost_rides"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_merchant_appointments"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE public.merchant_appointments
    SET status = 'cancelled', merchant_consent_status = 'denied'
    WHERE status = 'pending'
    AND merchant_consent_status = 'pending'
    AND created_at < NOW() - INTERVAL '2 minutes';
END;
$$;


ALTER FUNCTION "public"."cleanup_merchant_appointments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_rate_limit_log"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    DELETE FROM public.rate_limit_log
    WHERE window_start < NOW() - INTERVAL '1 hour';
END;
$$;


ALTER FUNCTION "public"."cleanup_rate_limit_log"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_stale_drivers"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE public.drivers
    SET is_online = false,
        updated_at = NOW()
    WHERE is_online = true
      AND last_location_update < NOW() - INTERVAL '5 minutes'
      AND active_ride_id IS NULL; -- Safety: never kick a driver during a trip
END;
$$;


ALTER FUNCTION "public"."cleanup_stale_drivers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clone_region_settings"("p_source_code" "text", "p_target_code" "text", "p_target_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_source region_settings%ROWTYPE;
    v_new_id UUID;
    v_result JSONB;
BEGIN
    SELECT * INTO v_source
    FROM region_settings
    WHERE code = p_source_code;

    IF v_source.id IS NULL THEN
        RETURN jsonb_build_object('error', format('Source region %s not found', p_source_code));
    END IF;

    INSERT INTO region_settings (
        code, name, currency, currency_symbol, locale, timezone,
        default_commission_rate, default_driver_payout_rate, default_merchant_split_rate,
        min_fare_cents, base_fare_cents, per_km_cents, per_min_cents,
        cancellation_fee_cents, max_wait_seconds, wait_fee_per_min_cents,
        gridlock_surcharge_cents, gridlock_delay_threshold_seconds,
        gps_proximity_dropoff_meters, gps_proximity_pickup_meters,
        max_offered_radius_meters, ride_offer_ttl_seconds,
        lease_daily_rate_cents, lease_mileage_rate_cents,
        driver_online_debt_limit_cents, ride_creation_debt_limit_cents,
        min_wallet_topup_cents, max_wallet_topup_cents,
        compliance_config, metadata, is_active
    ) VALUES (
        p_target_code,
        COALESCE(p_target_name, p_target_code),
        v_source.currency, v_source.currency_symbol, v_source.locale, v_source.timezone,
        v_source.default_commission_rate, v_source.default_driver_payout_rate, v_source.default_merchant_split_rate,
        v_source.min_fare_cents, v_source.base_fare_cents, v_source.per_km_cents, v_source.per_min_cents,
        v_source.cancellation_fee_cents, v_source.max_wait_seconds, v_source.wait_fee_per_min_cents,
        v_source.gridlock_surcharge_cents, v_source.gridlock_delay_threshold_seconds,
        v_source.gps_proximity_dropoff_meters, v_source.gps_proximity_pickup_meters,
        v_source.max_offered_radius_meters, v_source.ride_offer_ttl_seconds,
        v_source.lease_daily_rate_cents, v_source.lease_mileage_rate_cents,
        v_source.driver_online_debt_limit_cents, v_source.ride_creation_debt_limit_cents,
        v_source.min_wallet_topup_cents, v_source.max_wallet_topup_cents,
        v_source.compliance_config, v_source.metadata, v_source.is_active
    )
    RETURNING row_to_json(region_settings)::JSONB INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."clone_region_settings"("p_source_code" "text", "p_target_code" "text", "p_target_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."clone_region_settings"("p_source_code" "text", "p_target_code" "text", "p_target_name" "text") IS 'Clones all settings from an existing region to create a new region with identical config.';



CREATE OR REPLACE FUNCTION "public"."compute_avg_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    UPDATE public.profiles
    SET avg_rating = (
        SELECT COALESCE(ROUND(AVG(rating)::numeric, 2), 0)
        FROM public.ratings
        WHERE driver_id = NEW.driver_id
    ),
    total_ratings = (
        SELECT COUNT(*)
        FROM public.ratings
        WHERE driver_id = NEW.driver_id
    )
    WHERE id = NEW.driver_id;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."compute_avg_rating"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_cash_payment"("ride_uuid" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ride RECORD;
BEGIN
    SELECT * INTO v_ride FROM public.rides WHERE id = ride_uuid;
    
    -- 1. Caller must be assigned driver
    IF v_ride.driver_id != auth.uid() THEN
        RAISE EXCEPTION 'Not authorized: Caller is not the assigned driver';
    END IF;

    -- 2. Payment method must be cash
    IF v_ride.payment_method != 'cash' THEN
         RAISE EXCEPTION 'Invalid operation: Ride is not set to Cash';
    END IF;

    -- 3. Update State
    UPDATE public.rides 
    SET 
        cash_confirmed = TRUE, 
        payment_status = 'confirmed',
        updated_at = NOW()
    WHERE id = ride_uuid;
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."confirm_cash_payment"("ride_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_ride_atomic"("p_rider_id" "uuid", "p_pickup_lat" double precision, "p_pickup_lng" double precision, "p_pickup_address" "text", "p_dropoff_lat" double precision, "p_dropoff_lng" double precision, "p_dropoff_address" "text", "p_status" "text", "p_total_fare_cents" integer, "p_driver_payout_cents" integer, "p_distance_meters" integer, "p_duration_seconds" integer, "p_route_polyline" "text", "p_vehicle_type" "text", "p_payment_method" "text", "p_ride_pin" "text", "p_idempotency_key" "text", "p_metadata" "jsonb", "p_taxi_stand_id" "uuid", "p_billed_to_merchant_id" "uuid", "p_node_id" "uuid", "p_driver_cut" integer, "p_platform_cut" integer, "p_merchant_cut" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ride_id UUID;
    v_revenue_split_id UUID;
BEGIN
    INSERT INTO rides (
        rider_id,
        pickup_lat, pickup_lng, pickup_address,
        dropoff_lat, dropoff_lng, dropoff_address,
        status, total_fare_cents, driver_payout_cents,
        distance_meters, duration_seconds, route_polyline,
        vehicle_type, payment_method, ride_pin,
        idempotency_key, metadata,
        taxi_stand_id, billed_to_merchant_id
    ) VALUES (
        p_rider_id,
        p_pickup_lat, p_pickup_lng, p_pickup_address,
        p_dropoff_lat, p_dropoff_lng, p_dropoff_address,
        p_status, p_total_fare_cents, p_driver_payout_cents,
        p_distance_meters, p_duration_seconds, p_route_polyline,
        p_vehicle_type, p_payment_method, p_ride_pin,
        p_idempotency_key, p_metadata,
        p_taxi_stand_id, p_billed_to_merchant_id
    )
    RETURNING id INTO v_ride_id;

    INSERT INTO revenue_splits (
        ride_id, node_id, driver_id,
        platform_cut, driver_cut, merchant_cut, status
    ) VALUES (
        v_ride_id, p_node_id, NULL,
        p_platform_cut, p_driver_cut, p_merchant_cut, 'pending'
    )
    RETURNING id INTO v_revenue_split_id;

    RETURN jsonb_build_object(
        'ride_id', v_ride_id,
        'revenue_split_id', v_revenue_split_id,
        'success', true
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'error', SQLERRM,
        'success', false
    );
END;
$$;


