CREATE OR REPLACE FUNCTION "public"."credit_wallet"("p_user_id" "uuid", "p_amount_cents" integer, "p_type" "text", "p_description" "text" DEFAULT NULL::"text", "p_reference_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_lock_key INTEGER;
BEGIN
    IF p_reference_id IS NOT NULL THEN
        v_lock_key := hashtext(p_reference_id);
        PERFORM pg_advisory_xact_lock(v_lock_key);
        PERFORM 1 FROM wallet_transactions
        WHERE amount = p_amount_cents AND user_id = p_user_id
        AND (p_reference_id IS NULL OR description = 'ref:' || p_reference_id);
        IF FOUND THEN RETURN jsonb_build_object('success', true, 'duplicate', true); END IF;
    END IF;
    INSERT INTO wallet_transactions (user_id, amount, transaction_type, description, status)
    VALUES (p_user_id, p_amount_cents, p_type, COALESCE(p_description, 'ref:' || p_reference_id), 'completed');
    INSERT INTO wallets (user_id, balance_cents)
    VALUES (p_user_id, p_amount_cents)
    ON CONFLICT (user_id) DO UPDATE SET balance_cents = wallets.balance_cents + p_amount_cents, updated_at = now();
    RETURN jsonb_build_object('success', true, 'amount_cents', p_amount_cents);
END;
$$;


ALTER FUNCTION "public"."credit_wallet"("p_user_id" "uuid", "p_amount_cents" integer, "p_type" "text", "p_description" "text", "p_reference_id" "text") OWNER TO "postgres";


