CREATE OR REPLACE FUNCTION "public"."enforce_phone_uniqueness"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Skip if phone_number is null
  IF NEW.phone_number IS NULL THEN
    RETURN NEW;
  END IF;

  -- Check if phone exists in profiles table
  IF EXISTS (
    SELECT 1 FROM public.profiles
    WHERE phone_number = NEW.phone_number
    AND id != NEW.id  -- exclude self on update
  ) THEN
    RAISE EXCEPTION
      'Phone number % is already registered as a rider',
      NEW.phone_number;
  END IF;

  -- Check if phone exists in drivers table
  IF EXISTS (
    SELECT 1 FROM public.drivers
    WHERE phone_number = NEW.phone_number
    AND id != NEW.id  -- exclude self on update
  ) THEN
    RAISE EXCEPTION
      'Phone number % is already registered as a driver',
      NEW.phone_number;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_phone_uniqueness"() OWNER TO "postgres";


