CREATE OR REPLACE FUNCTION "public"."get_dealer_brokerage_report"("p_dealer_id" "uuid", "p_start_date" "date" DEFAULT (CURRENT_DATE - '30 days'::interval), "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("total_sales" bigint, "total_brokerage_cents" bigint, "total_sale_price_cents" bigint, "pending_cents" bigint, "paid_cents" bigint, "invoiced_cents" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*)::BIGINT AS total_sales,
        COALESCE(SUM(vs.brokerage_fee_cents), 0)::BIGINT AS total_brokerage_cents,
        COALESCE(SUM(vs.sale_price_cents), 0)::BIGINT AS total_sale_price_cents,
        COALESCE(SUM(vs.brokerage_fee_cents) FILTER (WHERE vs.status = 'financing_approved'), 0)::BIGINT AS pending_cents,
        COALESCE(SUM(vs.brokerage_fee_cents) FILTER (WHERE vs.brokerage_paid_at IS NOT NULL), 0)::BIGINT AS paid_cents,
        COALESCE(SUM(vs.brokerage_fee_cents) FILTER (WHERE vs.brokerage_invoiced_at IS NOT NULL AND vs.brokerage_paid_at IS NULL), 0)::BIGINT AS invoiced_cents
    FROM vehicle_sales vs
    WHERE vs.dealer_id = p_dealer_id
      AND vs.created_at >= p_start_date
      AND vs.created_at < p_end_date + INTERVAL '1 day';
END;
$$;


ALTER FUNCTION "public"."get_dealer_brokerage_report"("p_dealer_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_dealer_brokerage_report"("p_dealer_id" "uuid", "p_start_date" "date", "p_end_date" "date") IS 'Brokerage financial report for a dealer partner over a date range.';



CREATE OR REPLACE FUNCTION "public"."get_dealer_brokerage_report"("p_dealer_id" "uuid", "p_year" integer, "p_month" integer) RETURNS TABLE("total_sales" bigint, "total_revenue_cents" bigint, "total_commission_cents" bigint, "avg_sale_price_cents" numeric, "by_status" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*)::BIGINT,
        COALESCE(SUM(sale_price_cents), 0)::BIGINT,
        COALESCE(SUM(commission_cents), 0)::BIGINT,
        COALESCE(AVG(sale_price_cents), 0)::NUMERIC,
        COALESCE(
            (SELECT jsonb_agg(jsonb_build_object('status', s.status, 'count', s.c))
             FROM (SELECT vs.status, COUNT(*)::INT AS c
                   FROM public.vehicle_sales vs
                   WHERE vs.dealer_id = p_dealer_id
                   AND EXTRACT(YEAR FROM vs.created_at) = p_year
                   AND EXTRACT(MONTH FROM vs.created_at) = p_month
                   GROUP BY vs.status) s),
            '[]'::JSONB
        )
    FROM public.vehicle_sales
    WHERE dealer_id = p_dealer_id
      AND EXTRACT(YEAR FROM created_at) = p_year
      AND EXTRACT(MONTH FROM created_at) = p_month;
END;
$$;


ALTER FUNCTION "public"."get_dealer_brokerage_report"("p_dealer_id" "uuid", "p_year" integer, "p_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_demand_hint"("p_driver_lat" double precision, "p_driver_lng" double precision) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_nearby_searching integer;
BEGIN
  -- Count rides searching within 10km of driver
  SELECT COUNT(*) INTO v_nearby_searching
  FROM rides
  WHERE status IN ('searching', 'waiting_queue')
  AND created_at > NOW() - INTERVAL '5 minutes'
  AND (
    6371 * acos(
      LEAST(1.0, cos(radians(p_driver_lat)) * cos(radians(pickup_lat)) *
      cos(radians(pickup_lng) - radians(p_driver_lng)) +
      sin(radians(p_driver_lat)) * sin(radians(pickup_lat)))
    )
  ) < 10;

  IF v_nearby_searching >= 3 THEN
    RETURN 'HIGH DEMAND nearby — ' || v_nearby_searching || ' riders searching';
  ELSIF v_nearby_searching >= 1 THEN
    RETURN v_nearby_searching || ' rider' || CASE WHEN v_nearby_searching = 1 THEN '' ELSE 's' END || ' searching near you';
  ELSE
    RETURN 'Quiet right now — try POS or Chaguanas';
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_demand_hint"("p_driver_lat" double precision, "p_driver_lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_demand_hotspots"("p_min_score" numeric DEFAULT 1.4) RETURNS TABLE("area_hash" "text", "demand_score" numeric, "active_drivers" integer, "actual_demand" integer, "day_of_week" integer, "hour_of_day" integer)
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
    SELECT area_hash, demand_score, active_drivers, actual_demand, day_of_week, hour_of_day
    FROM demand_patterns
    WHERE demand_score >= p_min_score
      AND day_of_week = EXTRACT(DOW FROM now())::INTEGER
      AND hour_of_day = EXTRACT(HOUR FROM now())::INTEGER
    ORDER BY demand_score DESC LIMIT 20;
$$;


ALTER FUNCTION "public"."get_demand_hotspots"("p_min_score" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_demand_prediction"("p_lat" numeric, "p_lng" numeric, "p_radius_meters" integer DEFAULT 3000) RETURNS TABLE("area_hash" "text", "predicted_demand" integer, "active_drivers" integer, "demand_score" numeric, "recommendation" "text", "confidence" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_day INTEGER;
    v_hour INTEGER;
    v_target_hash TEXT;
BEGIN
    v_day := EXTRACT(DOW FROM NOW());
    v_hour := EXTRACT(HOUR FROM NOW());
    v_target_hash := substr(encode(digest(concat(p_lat::text, ',', p_lng::text), 'sha256'), 'hex'), 1, 8);
    
    RETURN QUERY
    WITH nearby_areas AS (
        SELECT 
            dp.area_hash,
            avg(dp.predicted_demand)::INTEGER as avg_predicted,
            avg(dp.actual_demand)::INTEGER as avg_actual,
            avg(dp.active_drivers)::INTEGER as avg_drivers,
            avg(dp.demand_score)::NUMERIC(4,2) as avg_score,
            count(*) as sample_count
        FROM demand_patterns dp
        WHERE dp.day_of_week = v_day
          AND dp.hour_of_day = v_hour
          AND dp.area_hash LIKE substr(v_target_hash, 1, 4) || '%'
          AND dp.created_at > NOW() - INTERVAL '28 days'
        GROUP BY dp.area_hash
    )
    SELECT 
        na.area_hash,
        na.avg_predicted as predicted_demand,
        na.avg_drivers as active_drivers,
        na.avg_score as demand_score,
        CASE 
            WHEN na.avg_score > 2.0 THEN 'HIGH_DEMAND_POSITION_HERE'
            WHEN na.avg_score > 1.5 THEN 'ELEVATED_DEMAND_GOOD_OPPORTUNITY'
            WHEN na.avg_score < 0.5 THEN 'LOW_DEMAND_CONSIDER_MOVING'
            ELSE 'NORMAL_DEMAND'
        END::TEXT as recommendation,
        least(na.sample_count / 4.0, 1.0)::NUMERIC as confidence
    FROM nearby_areas na
    ORDER BY na.avg_score DESC
    LIMIT 5;
END;
$$;


ALTER FUNCTION "public"."get_demand_prediction"("p_lat" numeric, "p_lng" numeric, "p_radius_meters" integer) OWNER TO "postgres";


