CREATE OR REPLACE FUNCTION "public"."get_fleet_lease_report"("p_region_id" "uuid", "p_year" integer, "p_month" integer) RETURNS TABLE("active_leases" bigint, "total_revenue_cents" bigint, "total_days_billed" bigint, "total_km_billed" bigint, "arrears_total_cents" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*) FILTER (WHERE status = 'active')::BIGINT,
        COALESCE(SUM(total_revenue_cents), 0)::BIGINT,
        COALESCE(SUM(total_days_billed), 0)::BIGINT,
        COALESCE(SUM(total_km_billed), 0)::BIGINT,
        COALESCE(SUM(daily_fee_arrears), 0)::BIGINT
    FROM public.fleet_leases
    WHERE region_id = p_region_id
      AND EXTRACT(YEAR FROM created_at) = p_year
      AND EXTRACT(MONTH FROM created_at) = p_month;
END;
$$;


ALTER FUNCTION "public"."get_fleet_lease_report"("p_region_id" "uuid", "p_year" integer, "p_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_fleet_lease_report"("p_lease_id" "uuid" DEFAULT NULL::"uuid", "p_driver_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" "date" DEFAULT (CURRENT_DATE - '30 days'::interval), "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("lease_id" "uuid", "driver_name" "text", "total_deductions" bigint, "total_deduction_cents" bigint, "failed_deductions" bigint, "failed_cents" bigint, "daily_charges" bigint, "mileage_charges" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        fl.id AS lease_id,
        COALESCE(p.full_name, 'Unknown') AS driver_name,
        COUNT(lp.id)::BIGINT AS total_deductions,
        COALESCE(SUM(lp.amount_cents) FILTER (WHERE lp.status = 'deducted'), 0)::BIGINT AS total_deduction_cents,
        COUNT(lp.id) FILTER (WHERE lp.status = 'failed')::BIGINT AS failed_deductions,
        COALESCE(SUM(lp.amount_cents) FILTER (WHERE lp.status = 'failed'), 0)::BIGINT AS failed_cents,
        COUNT(lp.id) FILTER (WHERE lp.deduction_type = 'daily')::BIGINT AS daily_charges,
        COUNT(lp.id) FILTER (WHERE lp.deduction_type IN ('mileage', 'hybrid'))::BIGINT AS mileage_charges
    FROM fleet_leases fl
    JOIN drivers d ON d.id = fl.driver_id
    LEFT JOIN profiles p ON p.id = d.user_id
    LEFT JOIN lease_payments lp ON lp.lease_id = fl.id
        AND lp.created_at >= p_start_date
        AND lp.created_at < p_end_date + INTERVAL '1 day'
    WHERE (p_lease_id IS NULL OR fl.id = p_lease_id)
      AND (p_driver_id IS NULL OR fl.driver_id = p_driver_id)
    GROUP BY fl.id, p.full_name;
END;
$$;


ALTER FUNCTION "public"."get_fleet_lease_report"("p_lease_id" "uuid", "p_driver_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_fleet_lease_report"("p_lease_id" "uuid", "p_driver_id" "uuid", "p_start_date" "date", "p_end_date" "date") IS 'Fleet lease financial report aggregated by lease over a date range.';



CREATE OR REPLACE FUNCTION "public"."get_home_suggestion"("p_rider_id" "uuid", "p_hour_of_day" smallint DEFAULT NULL::smallint) RETURNS TABLE("vertical" "text", "cta_text" "text", "cta_deep_link" "text", "reason_code" "text", "confidence" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_prog public.rider_progression%ROWTYPE;
  v_hour SMALLINT;
  v_cfg  RECORD;
BEGIN
  v_hour := COALESCE(p_hour_of_day, EXTRACT(HOUR FROM now())::smallint);
  SELECT * INTO v_prog FROM public.rider_progression WHERE rider_id = p_rider_id;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 'rides'::text, 'Where to?'::text, 'gtaxi://ride'::text, 'default'::text, 0.5::numeric;
    RETURN;
  END IF;

  IF v_prog.level > v_prog.notified_level THEN
    SELECT * INTO v_cfg FROM public.progression_config WHERE level = v_prog.level;
    IF FOUND THEN
      UPDATE public.rider_progression SET notified_level = v_prog.level WHERE rider_id = p_rider_id;
      RETURN QUERY SELECT v_cfg.unlock_vertical, v_cfg.push_body,
        ('gtaxi://' || v_cfg.unlock_vertical)::text, 'new_unlock'::text, 0.95::numeric;
      RETURN;
    END IF;
  END IF;

  IF v_hour BETWEEN 11 AND 14 AND 'grocery' = ANY(v_prog.unlocked_verticals) THEN
    RETURN QUERY SELECT 'grocery'::text, 'Lunch delivered in 30 min'::text, 'gtaxi://grocery'::text, 'time_of_day'::text, 0.80::numeric;
    RETURN;
  END IF;

  IF v_hour BETWEEN 17 AND 20 AND 'grocery' = ANY(v_prog.unlocked_verticals) THEN
    RETURN QUERY SELECT 'grocery'::text, 'Dinner sorted — order now'::text, 'gtaxi://grocery'::text, 'time_of_day'::text, 0.85::numeric;
    RETURN;
  END IF;

  IF v_hour BETWEEN 7 AND 9 AND v_prog.total_rides > 0 THEN
    RETURN QUERY SELECT 'rides'::text, 'Morning commute — book now'::text, 'gtaxi://ride'::text, 'time_of_day'::text, 0.72::numeric;
    RETURN;
  END IF;

  SELECT * INTO v_cfg FROM public.progression_config WHERE level > v_prog.level ORDER BY level ASC LIMIT 1;

  IF FOUND THEN
    DECLARE
      v_current  INTEGER := 0;
      v_required INTEGER := v_cfg.threshold_value;
      v_remain   INTEGER;
    BEGIN
      IF    v_cfg.threshold_type = 'rides'          THEN v_current := v_prog.total_rides;
      ELSIF v_cfg.threshold_type = 'grocery_orders' THEN v_current := v_prog.total_grocery_orders;
      ELSIF v_cfg.threshold_type = 'laundry_orders' THEN v_current := v_prog.total_laundry_orders;
      END IF;
      v_remain := GREATEST(0, v_required - v_current);
      IF v_remain > 0 THEN
        RETURN QUERY SELECT 'rides'::text,
          ('Book ' || v_remain || ' more ride' || CASE WHEN v_remain > 1 THEN 's' ELSE '' END || ' to unlock ' || v_cfg.unlock_vertical)::text,
          'gtaxi://ride'::text, 'next_unlock'::text, 0.60::numeric;
        RETURN;
      END IF;
    END;
  END IF;

  RETURN QUERY SELECT 'rides'::text, 'Where to?'::text, 'gtaxi://ride'::text, 'default'::text, 0.40::numeric;

EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT 'rides'::text, 'Where to?'::text, 'gtaxi://ride'::text, 'default'::text, 0.10::numeric;
END;
$$;


ALTER FUNCTION "public"."get_home_suggestion"("p_rider_id" "uuid", "p_hour_of_day" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_merchant_map_pins"("p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision DEFAULT 20) RETURNS TABLE("kiosk_id" "uuid", "merchant_id" "uuid", "merchant_name" "text", "category" "text", "location_name" "text", "lat" double precision, "lng" double precision, "default_services" "text"[], "is_open" boolean, "distance_meters" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
    SELECT
        k.id                  AS kiosk_id,
        m.id                  AS merchant_id,
        m.name                AS merchant_name,
        m.category,
        k.location_name,
        k.lat,
        k.lng,
        k.default_services,
        m.is_active           AS is_open,
        earth_distance(
            ll_to_earth(p_lat, p_lng),
            ll_to_earth(k.lat, k.lng)
        )                     AS distance_meters
    FROM kiosk_nodes k
    JOIN merchants m ON m.id = k.merchant_id
    JOIN merchant_subscriptions ms ON ms.merchant_id = m.id
    WHERE k.is_active = true
      AND m.is_active = true
      AND ms.status IN ('trial', 'active')
      AND k.lat IS NOT NULL
      AND k.lng IS NOT NULL
      AND earth_distance(
            ll_to_earth(p_lat, p_lng),
            ll_to_earth(k.lat, k.lng)
          ) <= p_radius_km * 1000
    ORDER BY m.is_pinned DESC, distance_meters ASC;
$$;


ALTER FUNCTION "public"."get_merchant_map_pins"("p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_nearby_merchants"("p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision DEFAULT 10, "p_store_type" "text" DEFAULT 'grocery'::"text") RETURNS TABLE("id" "uuid", "name" "text", "store_type" "text", "lat" double precision, "lng" double precision, "address" "text", "delivery_fee_cents" integer, "minimum_order_cents" integer, "avg_delivery_minutes" integer, "cover_image_url" "text", "is_open" boolean, "opens_at" time without time zone, "closes_at" time without time zone, "distance_meters" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT m.id, m.name, m.store_type,
         m.lat, m.lng, m.address,
         m.delivery_fee_cents, m.minimum_order_cents, m.avg_delivery_minutes,
         m.cover_image_url, m.is_open, m.opens_at, m.closes_at,
         ROUND(6371000 * acos(LEAST(1.0,
           cos(radians(p_lat)) * cos(radians(m.lat)) *
           cos(radians(m.lng) - radians(p_lng)) +
           sin(radians(p_lat)) * sin(radians(m.lat))
         )))::integer AS distance_meters
  FROM merchants m
  WHERE m.is_active = true
    AND m.activation_status = 'active'
    AND m.store_type = p_store_type
    AND m.lat IS NOT NULL AND m.lng IS NOT NULL
    AND 6371 * acos(LEAST(1.0,
          cos(radians(p_lat)) * cos(radians(m.lat)) *
          cos(radians(m.lng) - radians(p_lng)) +
          sin(radians(p_lat)) * sin(radians(m.lat))
        )) <= p_radius_km
  ORDER BY distance_meters ASC;
$$;


ALTER FUNCTION "public"."get_nearby_merchants"("p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision, "p_store_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_region_settings"("p_code" "text", "p_name" "text" DEFAULT NULL::"text", "p_currency" "text" DEFAULT 'TTD'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    INSERT INTO region_settings (code, name, currency)
    VALUES (
        p_code,
        COALESCE(p_name, p_code),
        p_currency
    )
    ON CONFLICT (code) DO UPDATE
        SET code = region_settings.code  -- no-op, just to get RETURNING
    RETURNING row_to_json(region_settings)::JSONB INTO v_result;

    RETURN v_result;
END;
$$;


