    LANGUAGE "sql" SECURITY DEFINER
    AS $$
    SELECT dq.order_id, m.name, dq.delivery_method, dq.status, dq.created_at, dq.attempts
    FROM dispatch_queue dq
    JOIN orders o ON o.id = dq.order_id
