CREATE OR REPLACE FUNCTION "public"."get_package_opportunities"() RETURNS TABLE("flight_id" "uuid", "flight_number" "text", "destination_code" "text", "departure_at" timestamp with time zone, "seats_available" integer, "wholesale_price" integer, "retail_price" integer, "margin_per_seat" integer)
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
    SELECT fi.id, fi.flight_number, fi.destination_code, fi.departure_at,
           fi.seats_total - fi.seats_reserved,
           fi.wholesale_price_cents, fi.retail_price_cents,
           fi.retail_price_cents - fi.wholesale_price_cents
    FROM flight_inventory fi
    WHERE fi.status = 'available'
      AND fi.departure_at > now() + INTERVAL '3 days'
      AND fi.seats_total - fi.seats_reserved >= 5
    ORDER BY fi.departure_at ASC LIMIT 10;
$$;


