CREATE OR REPLACE FUNCTION "public"."get_surge_multiplier_for_point"("p_lat" numeric, "p_lng" numeric) RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE v_multiplier NUMERIC := 1.0;
BEGIN
  SELECT COALESCE(MAX(multiplier), 1.0) INTO v_multiplier
  FROM pricing_zones
  WHERE is_active = true
    AND (expires_at IS NULL OR expires_at > now())
    AND center_lat IS NOT NULL AND center_lng IS NOT NULL
    AND (
      6371000 * 2 * ASIN(SQRT(
        POWER(SIN((p_lat - center_lat) * PI() / 180 / 2), 2) +
        COS(p_lat * PI() / 180) * COS(center_lat * PI() / 180) *
        POWER(SIN((p_lng - center_lng) * PI() / 180 / 2), 2)
      )) <= radius_meters
    );
  RETURN COALESCE(v_multiplier, 1.0);
END;
$$;


ALTER FUNCTION "public"."get_surge_multiplier_for_point"("p_lat" numeric, "p_lng" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_wallet_balance"("p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF p_user_id != auth.uid() THEN RAISE EXCEPTION 'Unauthorized'; END IF;
    RETURN COALESCE((SELECT balance_cents FROM wallets WHERE user_id = p_user_id), 0);
END;
$$;


