CREATE OR REPLACE FUNCTION "public"."increment_stop_wait_time"("p_stop_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_now TIMESTAMPTZ := now();
    v_last_ping TIMESTAMPTZ;
    v_delta_seconds INTEGER;
    v_is_waiting BOOLEAN;
BEGIN
    SELECT last_wait_ping_at, is_waiting INTO v_last_ping, v_is_waiting
    FROM public.ride_stops
    WHERE id = p_stop_id;

    IF v_is_waiting AND v_last_ping IS NOT NULL THEN
        v_delta_seconds := LEAST(60, EXTRACT(EPOCH FROM (v_now - v_last_ping))::INTEGER);
        
        IF v_delta_seconds > 0 THEN
            UPDATE public.ride_stops
            SET 
                total_wait_seconds = total_wait_seconds + v_delta_seconds,
                last_wait_ping_at = v_now,
                -- 2.5 cents per second = 150 cents per minute (TT$1.50/min Edge Out)
                wait_fee_cents = floor((total_wait_seconds + v_delta_seconds) * 2.5)
            WHERE id = p_stop_id;

            UPDATE public.rides
            SET stop_wait_seconds = COALESCE(stop_wait_seconds, 0) + v_delta_seconds
            WHERE id = (SELECT ride_id FROM public.ride_stops WHERE id = p_stop_id);
        END IF;
    ELSE
        UPDATE public.ride_stops
        SET 
            last_wait_ping_at = v_now,
            is_waiting = TRUE
        WHERE id = p_stop_id;
    END IF;
END;
$_$;


ALTER FUNCTION "public"."increment_stop_wait_time"("p_stop_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."increment_stop_wait_time"("p_stop_id" "uuid") IS 'Increments the wait timer for a specific stop at TT$1.50/min Edge Out rate (2.5 cents/sec). No grace period for intermediate stops.';



CREATE OR REPLACE FUNCTION "public"."is_coordinate_inside_active_zones"("p_lat" double precision, "p_lng" double precision) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF p_lat IS NULL OR p_lng IS NULL THEN
        RETURN false;
    END IF;
    RETURN EXISTS (
        SELECT 1 FROM public.active_zones z
        WHERE z.is_active = true
          AND ST_Covers(z.boundary, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography)
    );
END;
$$;


