CREATE OR REPLACE FUNCTION "public"."nearest_verified_pin"("p_lat" double precision, "p_lng" double precision, "p_max_results" integer DEFAULT 5) RETURNS TABLE("id" "text", "name" "text", "address" "text", "latitude" double precision, "longitude" double precision, "category" "text", "distance_meters" double precision)
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
    -- Return merchants first (highest priority)
    RETURN QUERY
    SELECT
        'merchant_' || m.id::text AS id,
        m.name,
        m.address,
        m.lat AS latitude,
        m.lng AS longitude,
        m.category,
        ST_Distance(
            ST_SetSRID(ST_MakePoint(m.lng, m.lat), 4326)::geography,
            ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
        ) AS distance_meters
    FROM merchants m
    WHERE m.is_pinned = true AND m.is_active = true
    AND m.lat IS NOT NULL AND m.lng IS NOT NULL
    ORDER BY distance_meters
    LIMIT p_max_results;

    -- If fewer than max_results, fill with locations
    RETURN QUERY
    SELECT
        'location_' || l.id::text AS id,
        l.name,
        l.address,
        l.latitude,
        l.longitude,
        l.category,
        ST_Distance(
            ST_SetSRID(ST_MakePoint(l.longitude, l.latitude), 4326)::geography,
            ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
        ) AS distance_meters
    FROM locations l
    ORDER BY distance_meters
    LIMIT p_max_results;
END;
$$;


ALTER FUNCTION "public"."nearest_verified_pin"("p_lat" double precision, "p_lng" double precision, "p_max_results" integer) OWNER TO "postgres";


