CREATE OR REPLACE FUNCTION "public"."post_reserve_contribution"("p_source_id" "uuid", "p_amount_cents" integer, "p_source_type" "text" DEFAULT 'ride'::"text") RETURNS TABLE("ledger_id" "uuid", "new_locked_cents" bigint, "new_health_ratio" numeric, "deployment_now_safe" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_id     UUID;
  v_locked BIGINT;
  v_target BIGINT;
  v_ratio  NUMERIC;
BEGIN
  IF p_amount_cents <= 0 THEN
    RAISE EXCEPTION 'reserve contribution must be positive, got %', p_amount_cents;
  END IF;

  INSERT INTO public.capital_reserve_ledger (ride_id, amount_cents, status, source_type, notes)
  VALUES (p_source_id, p_amount_cents, 'locked', p_source_type, 'auto:' || p_source_type)
  RETURNING id INTO v_id;

  UPDATE public.reserve_health SET
    locked_cents         = locked_cents + p_amount_cents,
    reserve_health_ratio = (locked_cents + p_amount_cents)::numeric / target_deployment_cents,
    computed_at          = now()
  WHERE id = true
  RETURNING locked_cents, target_deployment_cents, reserve_health_ratio
  INTO v_locked, v_target, v_ratio;

  RETURN QUERY SELECT v_id, v_locked, v_ratio, (v_ratio >= 1.0);
END;
$$;


ALTER FUNCTION "public"."post_reserve_contribution"("p_source_id" "uuid", "p_amount_cents" integer, "p_source_type" "text") OWNER TO "postgres";


