CREATE OR REPLACE FUNCTION "public"."secure_escape_booking"("p_escape_package_id" "uuid", "p_rider_id" "uuid", "p_guest_count" integer, "p_payment_method" "text" DEFAULT 'stripe'::"text", "p_pickup_address" "text" DEFAULT NULL::"text", "p_pickup_lat" double precision DEFAULT NULL::double precision, "p_pickup_lng" double precision DEFAULT NULL::double precision, "p_passenger_names" "jsonb" DEFAULT '[]'::"jsonb", "p_special_requests" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "message" "text", "reservation_id" "uuid", "total_price_cents" integer, "hold_expires_at" timestamp with time zone, "seats_remaining" integer, "requires_verification" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_flight_id        UUID;
    v_lodging_id       UUID;
    v_min_guests       INTEGER;
    v_max_guests       INTEGER;
    v_seats_avail      INTEGER;
    v_flight_status    TEXT;
    v_price_pp         INTEGER;
    v_req_verif        BOOLEAN;
    v_total            INTEGER;
    v_res_id           UUID;
    v_expires          TIMESTAMPTZ;
    v_reserve          INTEGER;
    v_pkg_max          INTEGER;
    v_pkg_alloc        INTEGER;
BEGIN
    -- 1. Lock escape_packages row first (consistent lock ordering to prevent deadlocks)
    SELECT ep.flight_block_id, ep.lodging_node_id, ep.price_per_person_cents,
           ep.max_total_guests, ep.allocated_guests
    INTO v_flight_id, v_lodging_id, v_price_pp, v_pkg_max, v_pkg_alloc
    FROM public.escape_packages ep
    WHERE ep.id = p_escape_package_id AND ep.is_active = TRUE
    FOR UPDATE;

    IF NOT FOUND THEN
        success := FALSE; message := 'Package not found or no longer available.';
        RETURN NEXT; RETURN;
    END IF;

    -- 2. Validate per-group occupancy bounds
    SELECT ln.min_guests, ln.max_guests, ln.requires_verification
    INTO v_min_guests, v_max_guests, v_req_verif
    FROM public.lodging_nodes ln WHERE ln.id = v_lodging_id;

    IF p_guest_count < v_min_guests OR p_guest_count > v_max_guests THEN
        success               := FALSE;
        message               := 'Guest count must be between ' || v_min_guests || ' and ' || v_max_guests || '.';
        requires_verification := v_req_verif;
        RETURN NEXT; RETURN;
    END IF;

    -- 3. Validate total package guest cap (villa capacity across all reservations)
    IF (v_pkg_alloc + p_guest_count) > v_pkg_max THEN
        success         := FALSE;
        message         := 'Package fully subscribed. Only ' || (v_pkg_max - v_pkg_alloc) || ' guest slot(s) remain.';
        seats_remaining := v_pkg_max - v_pkg_alloc;
        RETURN NEXT; RETURN;
    END IF;

    -- 4. Lock flight block row (second lock — always escape_packages before flight_blocks)
    SELECT (fb.total_capacity_seats - fb.allocated_seats), fb.status
    INTO v_seats_avail, v_flight_status
    FROM public.flight_blocks fb WHERE fb.id = v_flight_id FOR UPDATE;

    IF v_flight_status = 'CANCELLED' THEN
        success := FALSE; message := 'This flight has been cancelled.';
        seats_remaining := 0; RETURN NEXT; RETURN;
    END IF;

    IF v_seats_avail < p_guest_count THEN
        success         := FALSE;
        message         := 'Only ' || v_seats_avail || ' seat(s) remaining on this flight.';
        seats_remaining := v_seats_avail; RETURN NEXT; RETURN;
    END IF;

    -- 5. Atomically allocate seats + guest count
    UPDATE public.flight_blocks
    SET allocated_seats = allocated_seats + p_guest_count, updated_at = now()
    WHERE id = v_flight_id;

    UPDATE public.escape_packages
    SET allocated_guests = allocated_guests + p_guest_count, updated_at = now()
    WHERE id = p_escape_package_id;

    -- 6. Compute totals
    v_total   := v_price_pp * p_guest_count;
    v_reserve := ROUND(v_total * 0.015);
    v_expires := now() + INTERVAL '10 minutes';

    INSERT INTO public.package_reservations (
        escape_package_id, flight_block_id, rider_id, guest_count,
        total_price_cents, status, payment_method, hold_expires_at,
        pickup_address, pickup_lat, pickup_lng,
        passenger_names, special_requests, reserve_amount_cents
    ) VALUES (
        p_escape_package_id, v_flight_id, p_rider_id, p_guest_count,
        v_total, 'ACTIVE_HOLD', p_payment_method, v_expires,
        p_pickup_address, p_pickup_lat, p_pickup_lng,
        p_passenger_names, p_special_requests, v_reserve
    ) RETURNING id INTO v_res_id;

    success               := TRUE;
    message               := 'Seats held. Complete payment within 10 minutes to secure your escape.';
    reservation_id        := v_res_id;
    total_price_cents     := v_total;
    hold_expires_at       := v_expires;
    seats_remaining       := v_seats_avail - p_guest_count;
    requires_verification := v_req_verif;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."secure_escape_booking"("p_escape_package_id" "uuid", "p_rider_id" "uuid", "p_guest_count" integer, "p_payment_method" "text", "p_pickup_address" "text", "p_pickup_lat" double precision, "p_pickup_lng" double precision, "p_passenger_names" "jsonb", "p_special_requests" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_zone"("p_lat" double precision, "p_lng" double precision, "p_territory_name" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_pt geography := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography;
    v_id uuid;
BEGIN
    SELECT id INTO v_id
    FROM public.seeded_zones
    WHERE ST_DWithin(location, v_pt, 500)
    ORDER BY ST_Distance(location, v_pt)
    LIMIT 1;

    IF v_id IS NOT NULL THEN
        UPDATE public.seeded_zones
           SET seed_count = seed_count + 1, updated_at = now()
         WHERE id = v_id;
    ELSE
        INSERT INTO public.seeded_zones (lat, lng, location, territory_name)
        VALUES (p_lat, p_lng, v_pt, p_territory_name);
    END IF;
END;
$$;


ALTER FUNCTION "public"."seed_zone"("p_lat" double precision, "p_lng" double precision, "p_territory_name" "text") OWNER TO "postgres";


