    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    splits jsonb;
BEGIN
    IF NEW.total_fare_cents IS NOT NULL AND NEW.total_fare_cents > 0 THEN
        splits := public.calculate_fare_split(NEW.total_fare_cents);

        NEW.driver_payout_cents := (splits->>'driver_share_cents')::integer;
        NEW.platform_fee_cents  := (splits->>'platform_fee_cents')::integer;
        NEW.reserve_cents       := (splits->>'reserve_fee_cents')::integer;
    END IF;

    RETURN NEW;
END;
$$;


