        format('Area %s demand_score %.2f (drivers: %s, demand: %s) at hour %s',
            NEW.area_hash, NEW.demand_score, NEW.active_drivers, NEW.actual_demand, NEW.hour_of_day),
        'demand_patterns_trigger',
        jsonb_build_object('area_hash', NEW.area_hash, 'demand_score', NEW.demand_score,
            'active_drivers', NEW.active_drivers, 'actual_demand', NEW.actual_demand,
            'hour', NEW.hour_of_day, 'dow', NEW.day_of_week)
    );
    RETURN NEW;
END;
