    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- We call the edge function via an asynchronous HTTP request.
  -- This ensures the signup process isn't slowed down by Stripe's API.
  PERFORM
