CREATE OR REPLACE FUNCTION "public"."update_driver_acceptance_rate"("p_driver_id" "uuid", "p_accepted" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE drivers
    SET acceptance_rate = CASE
        WHEN p_accepted THEN LEAST(COALESCE(acceptance_rate, 0.8) * 0.95 + 0.05, 1.0)
        ELSE GREATEST(COALESCE(acceptance_rate, 0.8) * 0.90, 0.1)
    END
    WHERE id = p_driver_id;
END;
$$;


