CREATE MATERIALIZED VIEW "public"."hot_zones" AS
 SELECT "area_hash",
    "avg"("predicted_demand") AS "avg_predicted",
    "avg"("actual_demand") AS "avg_actual",
    "avg"("demand_score") AS "avg_score",
    "day_of_week",
    "hour_of_day",
    "max"("updated_at") AS "last_updated"
   FROM "public"."demand_patterns"
  WHERE ("created_at" > ("now"() - '7 days'::interval))
  GROUP BY "area_hash", "day_of_week", "hour_of_day"
 HAVING ("avg"("demand_score") > 1.5)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."hot_zones" OWNER TO "postgres";


