    CONSTRAINT "orders_payment_method_check" CHECK (("payment_method" = ANY (ARRAY['card'::"text", 'cash'::"text", 'wallet'::"text"]))),
    CONSTRAINT "orders_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['pending'::"text", 'authorized'::"text", 'captured'::"text", 'failed'::"text", 'refunded'::"text"]))),
    CONSTRAINT "orders_substitution_policy_check" CHECK (("substitution_policy" = ANY (ARRAY['contact'::"text", 'substitute'::"text", 'cancel'::"text"])))
);


