COMMENT ON COLUMN "public"."orders"."task_type" IS 'Unified service type: transport, fulfillment, barber, carwash, laundry, grocery, etc.';



COMMENT ON COLUMN "public"."orders"."puck_id" IS 'NFC tag_uid of the Smart Puck that generated this order. Links to kiosk_nodes.tag_uid.';



CREATE OR REPLACE VIEW "public"."merchant_orders" AS
 SELECT "o"."id",
    "o"."status",
    "o"."created_at",
    "o"."total_cents" AS "total",
    "o"."merchant_id",
    "m"."created_by" AS "merchant_user_id",
    "o"."rider_id",
    "o"."delivery_driver_id",
    "o"."delivery_address",
    "o"."payment_status",
    "o"."updated_at"
   FROM ("public"."orders" "o"
     JOIN "public"."merchants" "m" ON (("m"."id" = "o"."merchant_id")))
  WHERE ("o"."merchant_id" IS NOT NULL);


