    CONSTRAINT "wallet_transactions_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'completed'::"text", 'failed'::"text"]))),
    CONSTRAINT "wallet_transactions_transaction_type_check" CHECK (("transaction_type" = ANY (ARRAY['topup'::"text", 'ride_payment'::"text", 'refund'::"text", 'bonus'::"text", 'driver_payout'::"text", 'tip'::"text", 'commission_fee'::"text", 'cancellation_fee'::"text", 'leakage_fine'::"text", 'debt_recovery'::"text", 'payout'::"text", 'debt_repayment'::"text", 'lease_deduction'::"text", 'lease_income'::"text", 'capital_reserve'::"text", 'merchant_commission'::"text", 'travel_package_payment'::"text", 'travel_package_refund'::"text", 'scout_referral_payout'::"text", 'referral_bonus'::"text", 'merchant_subscription'::"text"])))
