COMMENT ON TABLE "public"."wallet_transactions" IS 'Financial ledger for all user and driver funds. Truth is Sum(amount).';



CREATE OR REPLACE VIEW "public"."merchant_wallet_balance" AS
 SELECT "m"."id" AS "merchant_id",
    "m"."name" AS "merchant_name",
    COALESCE("sum"("wt"."amount"), (0)::bigint) AS "balance_cents",
    "count"("wt"."id") AS "transaction_count",
    COALESCE("sum"("wt"."amount") FILTER (WHERE ("wt"."transaction_type" = 'merchant_commission'::"text")), (0)::bigint) AS "total_commission_earned_cents",
    "max"("wt"."created_at") AS "last_commission_at"
   FROM ("public"."merchants" "m"
     LEFT JOIN "public"."wallet_transactions" "wt" ON ((("wt"."user_id" = "m"."created_by") AND ("wt"."status" = 'completed'::"text"))))
  GROUP BY "m"."id", "m"."name";


