);


ALTER TABLE "public"."rides" OWNER TO "postgres";


COMMENT ON COLUMN "public"."rides"."rating" IS 'The 1-5 star rating the rider gave the driver for this completed ride. Used for Tier 1 Familiarity Dispatch.';



COMMENT ON COLUMN "public"."rides"."entertainment_url" IS 'The Spotify or YouTube URL suggested by the rider.';



COMMENT ON COLUMN "public"."rides"."entertainment_status" IS 'The driver approval state for the music suggestion.';



COMMENT ON COLUMN "public"."rides"."pickup_wait_seconds" IS 'Wait time at initial arrival before ride start (Eligible for 3-min grace)';



COMMENT ON COLUMN "public"."rides"."stop_wait_seconds" IS 'Wait time at intermediate stops (Billed per second, no grace)';



COMMENT ON COLUMN "public"."rides"."idempotency_key" IS 'Client-generated UUID to prevent duplicate ride requests during network retries.';



COMMENT ON COLUMN "public"."rides"."safe_entry" IS 'When true, driver is instructed to wait until rider is safely inside their destination before closing the ride.';



