CREATE OR REPLACE VIEW "public"."v_merchant_revenue_summary" WITH ("security_invoker"='true') AS
 SELECT "merchant_id",
    "date_trunc"('month'::"text", "created_at") AS "month",
    "count"("id") AS "total_transactions",
    "sum"("gross_amount_cents") AS "total_gross_cents",
    "sum"("platform_fee_cents") AS "total_platform_commission_cents",
    "sum"("merchant_split_cents") AS "total_merchant_earnings_cents"
   FROM "public"."platform_revenue_logs"
  GROUP BY "merchant_id", ("date_trunc"('month'::"text", "created_at"));


